class _KeywordMessageExceptionFactory(Protocol):
    def __call__(self, *, message: str) -> Exception: ...


def _build_exception(exc_type: type[Exception], message: str) -> Exception:
    try:
        return exc_type(message)
    except TypeError:
        return cast(_KeywordMessageExceptionFactory, exc_type)(message=message)


