def query_first_row_post_op(
    *,
    strict_one: bool,
    model_cls: type[DatabaseObjectRow[Any]] | None = None,
    select_columns: tuple[str, ...] | None = None,
    required_error_message: str | None = None,
) -> CompiledPostOp:
    """Return the first SQL row, optionally hydrated, enforcing cardinality."""

    raw_mode = model_cls is None
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            model_cls=model_cls,
            strict_one=strict_one,
            raw_mode=raw_mode,
            select_columns=select_columns,
            literal_payload=({"empty_message": required_error_message} if raw_mode and required_error_message is not None else None),
            terminal_materializer=(
                TerminalMaterializerKind.REQUIRED_RAW_ROW if raw_mode and required_error_message is not None else None
            ),
            terminal_object_empty=(
                TerminalObjectEmptySpec(
                    kind=TerminalObjectEmptyKind.VALUE_ERROR,
                    message=required_error_message,
                )
                if model_cls is not None and required_error_message is not None
                else None
            ),
        ),
    )


