_INTERNAL_RESULT_COLUMNS = frozenset(
    {
        "__compound_step__",
        "__compound_parent_step__",
        "__ref_id",
        "__return_many",
        "__ordinal",
    },
)


def _row_dict(row: Mapping[str, object] | object) -> dict[str, object]:
    items = getattr(row, "items", None)
    if callable(items) and not isinstance(row, Mapping):
        row_dict = {str(key): value for key, value in cast("Callable[[], Iterable[tuple[object, object]]]", items)()}
        return {key: value for key, value in row_dict.items() if key not in _INTERNAL_RESULT_COLUMNS}
    keys = getattr(row, "keys", None)
    if callable(keys) and not isinstance(row, Mapping):
        if not isinstance(row, Iterable):
            msg = f"Row object with keys() is not iterable: {type(row).__name__}"
            raise TypeError(msg)
        row_values: Iterable[object] = cast(Iterable[object], row)
        row_keys = cast(Iterable[object], keys())
        key_values = tuple(str(key) for key in row_keys)
        row_dict = dict(zip(key_values, row_values, strict=True))
    else:
        row_dict = dict(cast("Mapping[str, object]", row))
    return {key: value for key, value in row_dict.items() if key not in _INTERNAL_RESULT_COLUMNS}


def _maybe_row_dict(row: object) -> dict[str, object] | None:
    try:
        return _row_dict(row)
    except (TypeError, ValueError):
        return None


def _projected_column_value(
    row_dict: Mapping[str, object],
    column: str,
    model_cls: type[DatabaseObjectRow[Any]] | None,
) -> object:
    target_type: object | None = None
    if model_cls is not None:
        field_info = model_cls.model_fields.get(column)
        if field_info is not None:
            target_type = field_info.annotation
    if column in row_dict:
        value = row_dict[column]
        return _coerce_dataclass_field_value(value, target_type) if target_type is not None else value
    if model_cls is not None:
        from l1000_schema.column_utils import get_db_column_name

        db_column = get_db_column_name(model_cls, DynamicFieldName(column))
        if db_column in row_dict:
            value = row_dict[db_column]
            return _coerce_dataclass_field_value(value, target_type) if target_type is not None else value
    db_alias = f"db_{column}"
    if db_alias in row_dict:
        value = row_dict[db_alias]
        return _coerce_dataclass_field_value(value, target_type) if target_type is not None else value
    return _PROJECTED_COLUMN_MISSING


def _project_raw_selected_columns(
    spec: ResultMaterializationSpec,
    row_dict: Mapping[str, object],
) -> dict[str, object]:
    assert spec.select_columns is not None
    projected: dict[str, object] = {}
    for column in spec.select_columns:
        value = _projected_column_value(row_dict, column, spec.model_cls)
        if value is not _PROJECTED_COLUMN_MISSING:
            projected[column] = value
    return projected


def _row_marks_deleted(
    row_dict: Mapping[str, object],
    model_cls: type[DatabaseObjectRow[Any]] | None,
) -> bool:
    if row_dict.get("deleted") in (True, 1) or row_dict.get("sys_deleted") in (True, 1):
        return True
    if model_cls is not None:
        from l1000_schema.column_utils import get_db_column_name

        deleted_column = get_db_column_name(model_cls, DynamicFieldName("deleted"))
        if row_dict.get(deleted_column) in (True, 1):
            return True
    return False


def _result_row_by_columns(raw: RawResult, required_columns: frozenset[str]) -> dict[str, object]:
    for row in raw:
        row_dict = _row_dict(cast("Mapping[str, object]", row))
        if required_columns.issubset(row_dict):
            return row_dict
    return {}


def _revision_id_or_none(value: object) -> RevisionId | None:
    if value is None:
        return None
    if isinstance(value, RevisionId):
        return value
    return RevisionId(str(value))


def _normalize_json_container_numbers(value: object) -> object:
    # Exact JSON scalar types cannot contain numbers that need recursive conversion.
    # Subclasses still follow the existing Decimal/Mapping/list dispatch below.
    if value is None or type(value) in (str, int, float, bool):
        return value
    if isinstance(value, Decimal):
        return int(value) if value == value.to_integral_value() else float(value)
    if isinstance(value, Mapping):
        return {str(key): _normalize_json_container_numbers(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_json_container_numbers(item) for item in value]
    return value


def _rows_as_dicts(raw: RawResult) -> list[dict[str, object]]:
    rows = [_row_dict(cast("Mapping[str, object]", row)) for row in raw]
    return [{key: _normalize_json_container_numbers(value) for key, value in row.items()} for row in rows]


def _dataclass_field_candidate_types(target_type: object) -> tuple[type[object], ...]:
    origin = get_origin(target_type)
    if origin in {Union, UnionType}:
        raw_candidates = tuple(arg for arg in get_args(target_type) if arg is not type(None))
    else:
        raw_candidates = (target_type,)
    return tuple(candidate for candidate in raw_candidates if isinstance(candidate, type))


def _coerce_dataclass_field_value(value: object, target_type: object) -> object:
    if value is None:
        return None
    for candidate in _dataclass_field_candidate_types(target_type):
        if issubclass(candidate, (SysId, BranchId, RevisionId, ConnectionId, WorkspaceId)):
            return value if type(value) is candidate else cast("type[Any]", candidate)(str(value))
        if isinstance(value, candidate):
            return value
        if issubclass(candidate, Enum):
            return candidate(value)
        if candidate is bool:
            return _coerce_scalar(value, ScalarCoercionKind.BOOL)
        if candidate in {int, float, str}:
            return cast("type[Any]", candidate)(value)
        if isinstance(value, str) and issubclass(candidate, (SysId, BranchId, RevisionId, ConnectionId, WorkspaceId)):
            return cast("type[Any]", candidate)(value)
        if isinstance(value, str) and issubclass(candidate, UUID):
            return candidate(value)
    return value


def _materialize_hydrate_dict_one(
    spec: ResultMaterializationSpec,
    raw: RawResult,
) -> object | None:
    if not raw:
        return None
    if spec.model_cls is None:
        if spec.result_cls is not None and is_dataclass(spec.result_cls):
            from l2070_batching.post_op_structured import decode_dataclass_one

            return decode_dataclass_one(spec.result_cls, raw)
        msg = "HYDRATE_DICT_ONE materialization requires a model class or dataclass result class."
        raise ValueError(msg)
    if not raw:
        return None
    from impl.common.l2070_server_plan.steps._compile_helpers import hydrate_dict_one_post_op

    return cast(
        "dict[str, object] | None",
        hydrate_dict_one_post_op(
            spec.model_cls,
            None if spec.select_columns is None else list(spec.select_columns),
        )(raw, None),
    )


def _materialize_hydrate_dict_many(
    spec: ResultMaterializationSpec,
    raw: RawResult,
) -> list[object]:
    if spec.model_cls is None:
        if spec.result_cls is not None and is_dataclass(spec.result_cls):
            from l2070_batching.post_op_structured import decode_dataclass_one

            materialized = [decode_dataclass_one(spec.result_cls, [row]) for row in raw]
            return [item for item in materialized if item is not None]
        msg = "HYDRATE_DICT_MANY materialization requires a model class or dataclass result class."
        raise ValueError(msg)
    from impl.common.l2070_server_plan.steps._compile_helpers import hydrate_dict_many_post_op

    return cast(
        "list[object]",
        hydrate_dict_many_post_op(
            spec.model_cls,
            None if spec.select_columns is None else list(spec.select_columns),
        )(raw, None),
    )


def _strip_columns_from_spec(spec: ResultMaterializationSpec) -> tuple[str, ...]:
    return () if spec.select_columns is None else tuple(spec.select_columns)


def _require_row(raw: RawResult, row_index: int = 0) -> Mapping[str, object]:
    try:
        return cast("Mapping[str, object]", dict(raw[row_index]))
    except IndexError as exc:
        msg = f"Expected row {row_index}, got {len(raw)} rows."
        raise IndexError(msg) from exc


def _decoder_payload(spec: ResultMaterializationSpec) -> object | None:
    """Return the closed decoder payload associated with a materialization spec."""
    if isinstance(spec.terminal_literal, DecoderConfig):
        return spec.terminal_literal.payload
    return spec.literal_payload


def _scalar_from_row(row: Mapping[str, object], column: str | None) -> object:
    if column is not None:
        return row.get(column)
    if len(row) == 1:
        return next(iter(row.values()))
    msg = "Scalar materialization requires a column when the row has multiple columns."
    raise ValueError(msg)


def _coerce_scalar(value: object, coercion: ScalarCoercionKind) -> object:
    if value is None or coercion is ScalarCoercionKind.NONE:
        return value
    if coercion is ScalarCoercionKind.BOOL:
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"1", "true", "t", "yes", "y"}:
                return True
            if lowered in {"0", "false", "f", "no", "n", ""}:
                return False
        return bool(value)
    if coercion is ScalarCoercionKind.INT:
        if isinstance(value, str | bytes | bytearray | SupportsInt):
            return int(value)
        msg = f"Cannot coerce {type(value).__name__} to int."
        raise TypeError(msg)
    if coercion is ScalarCoercionKind.STR:
        return str(value)
    uuid_value: UUID | str = (
        UUID(bytes=bytes(value))
        if isinstance(value, bytes | bytearray | memoryview)
        else value
        if isinstance(value, UUID | str)
        else str(value)
    )
    if coercion is ScalarCoercionKind.SYS_ID:
        from l1400_types import SysId

        return value if isinstance(value, SysId) else SysId(uuid_value)
    if coercion is ScalarCoercionKind.BRANCH_ID:
        from l7000_versioned_schema.versioned_schema import BranchId

        return value if isinstance(value, BranchId) else BranchId(uuid_value)
    if coercion is ScalarCoercionKind.REVISION_ID:
        from l7000_versioned_schema.versioned_schema import RevisionId

        return value if isinstance(value, RevisionId) else RevisionId(uuid_value)
    if coercion is ScalarCoercionKind.WORKSPACE_ID:
        from l1400_types import WorkspaceId

        return value if isinstance(value, WorkspaceId) else WorkspaceId(uuid_value)
    if coercion is ScalarCoercionKind.BRANCH_TIP_MATERIALIZATION:
        from l7000_versioned_schema.versioned_schema import BranchTipMaterialization

        return value if isinstance(value, BranchTipMaterialization) else BranchTipMaterialization(str(value))
    if coercion is ScalarCoercionKind.BRANCHPOINT_MATERIALIZATION:
        from l7000_versioned_schema.versioned_schema import BranchPointMaterialization

        return value if isinstance(value, BranchPointMaterialization) else BranchPointMaterialization(str(value))
    if coercion is ScalarCoercionKind.USER_ID:
        from l4000_permissions.rbac_ids import UserId

        return value if isinstance(value, UserId) else UserId(str(value))
    if coercion is ScalarCoercionKind.QUEUE_MESSAGE_ID:
        from l4100_queue.queue_message import QueueMessageId

        if isinstance(value, QueueMessageId):
            return value
        if isinstance(value, UUID | str):
            return QueueMessageId(value)
        return QueueMessageId(str(value))
    if coercion is ScalarCoercionKind.JSON:
        if isinstance(value, str):
            from json import loads

            return loads(value)
        return value
    msg = f"Unsupported scalar coercion: {coercion.value}"
    raise ValueError(msg)


def coerce_scalar_value(value: object, coercion: ScalarCoercionKind) -> object:
    """Apply the scalar coercion used by compiled post-operations."""
    return _coerce_scalar(value, coercion)


def _materialize_scalar_column(spec: ResultMaterializationSpec, raw: RawResult) -> object:
    if not raw and spec.use_default_on_empty:
        return spec.default_value
    if not raw:
        return None
    if spec.scalar_aggregation is ScalarAggregationKind.SUM_ROWS:
        scalar_value_column = spec.scalar_value_column
        assert scalar_value_column is not None
        scalar_key = scalar_value_column.to_row_key()
        total = 0
        saw_value = False
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            if scalar_key not in row_dict:
                continue
            scalar_value = row_dict[scalar_key]
            if not isinstance(scalar_value, int | float | Decimal | str | bytes | bytearray):
                msg = f"Scalar aggregation column {scalar_key!r} requires an integer-compatible value, got {type(scalar_value).__name__}."
                raise TypeError(msg)
            saw_value = True
            total += int(scalar_value)
        if saw_value:
            return _coerce_scalar(total, spec.scalar_coercion)
    value = _scalar_from_row(_require_row(raw, spec.row_index), spec.column)
    if value is None and spec.use_default_on_empty:
        value = spec.default_value
    return _coerce_scalar(value, spec.scalar_coercion)


def _materialize_scalar_column_list(spec: ResultMaterializationSpec, raw: RawResult) -> list[object]:
    values: list[object] = []
    for row in raw:
        value = _scalar_from_row(cast("Mapping[str, object]", dict(row)), spec.column)
        if value is not None:
            coerced = _coerce_scalar(value, spec.scalar_coercion)
            if spec.target_type is not None:
                coerced = spec.target_type(coerced)
            values.append(coerced)
    return values


def _require_mapping_payload(value: object, context: str) -> Mapping[str, object]:
    if not isinstance(value, Mapping):
        msg = f"{context} materialization requires mapping payload."
        raise TypeError(msg)
    return cast("Mapping[str, object]", value)


def _materialize_scalar_tuple(spec: ScalarTupleResultSpec, raw: RawResult) -> object:
    if not raw:
        if spec.return_none_on_empty:
            return None
        return spec.default_values
    row = _row_dict(_require_row(raw))
    values: list[object] = []
    for column, default in zip(spec.column_names, spec.default_values, strict=True):
        value = row.get(column)
        if value is None:
            value = default
        if isinstance(default, bool):
            values.append(_coerce_scalar(value, ScalarCoercionKind.BOOL))
            continue
        if isinstance(default, int) and not isinstance(value, bool):
            values.append(int(cast("int | float | str | bytes", value)))
            continue
        values.append(value)
    return tuple(values)


def _normalize_deleted_count_value(value: object, value_column: LockedColumnName) -> int:
    if isinstance(value, int):
        return max(0, value)
    row_key = value_column.to_row_key()
    if isinstance(value, Mapping):
        if row_key not in value:
            msg = f"Deleted-count row does not contain declared value column {row_key!r}."
            raise ValueError(msg)
        return max(0, int(value[row_key]))
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        count = 0
        for row in value:
            if not isinstance(row, Mapping) or row_key not in row:
                msg = f"Deleted-count row does not contain declared value column {row_key!r}."
                raise ValueError(msg)
            count += max(0, int(row[row_key]))
        return count
    msg = (
        "Deleted-count materialization requires an integer, a declared count row, "
        f"or a sequence of declared count rows; got {type(value).__name__}."
    )
    raise TypeError(msg)


def _materialize_scalar_row_value(spec: ScalarRowValueSpec[Any], raw: RawResult) -> object:
    if spec.kind is ScalarRowValueKind.DELETED_COUNT_BOOL:
        return _normalize_deleted_count_value(raw, spec.payload.value_column) > 0
    msg = f"Unsupported scalar row value kind: {spec.kind.value}"
    raise ValueError(msg)


def _assert_vector_dimension_validation(
    payload: VectorDimensionValidationAssertionSpec,
    raw: RawResult,
    *,
    message: str | None,
) -> None:
    if not raw:
        return
    row = _row_dict(_require_row(raw))
    if bool(row.get(payload.ok_column, True)):
        return
    from l1100_exceptions.exceptions import VectorDimensionMismatchError

    expected = row.get(payload.expected_dimensions_column)
    actual = row.get(payload.actual_dimensions_column)
    detail = message or f"Vector dimension mismatch: expected {expected}, got {actual}."
    expected_dimension_value = int(cast("int | float | str | bytes", expected)) if expected is not None else None
    actual_dimension_value = int(cast("int | float | str | bytes", actual)) if actual is not None else None
    raise VectorDimensionMismatchError(
        detail,
        expected_dimensions=expected_dimension_value,
        actual_dimensions=actual_dimension_value,
    )


def _materialize_assertion_from_row(spec: ResultAssertionFromRowSpec[Any], raw: RawResult) -> None:
    if spec.kind is RowAssertionKind.VECTOR_DIMENSION_VALIDATION:
        _assert_vector_dimension_validation(
            cast(VectorDimensionValidationAssertionSpec, spec.payload),
            raw,
            message=spec.message,
        )
        return
    msg = f"Unsupported row assertion kind: {spec.kind.value}"
    raise ValueError(msg)


def _materialize_terminal_scalar(spec: ResultMaterializationSpec, raw: RawResult) -> object:
    if spec.scalar_tuple is not None:
        return _materialize_scalar_tuple(spec.scalar_tuple, raw)
    if spec.scalar_row_value is not None:
        return _materialize_scalar_row_value(spec.scalar_row_value, raw)
    if spec.column is None and not spec.first_row_scalar:
        return _coerce_scalar(len(raw), spec.scalar_coercion)
    if not raw and spec.error_message is not None:
        message = str(spec.error_message or f"Required column {spec.column!r} was not returned.")
        raise ValueError(message)
    if spec.model_cls is not None and raw:
        column = spec.column
        if column is None:
            value = _materialize_scalar_column(spec, raw)
        else:
            value = _projected_column_value(_row_dict(_require_row(raw, spec.row_index)), column, spec.model_cls)
        if value is _PROJECTED_COLUMN_MISSING:
            value = None
    else:
        value = _materialize_scalar_column(spec, raw)
    if value is None and spec.error_message is not None:
        message = str(spec.error_message or f"Required column {spec.column!r} was not returned.")
        raise ValueError(message)
    return value


def _raise_terminal_object_empty(
    empty_spec: TerminalObjectEmptySpec | None,
    model_cls: type[BaseModel],
) -> None:
    """Apply the compile-time-selected policy for an empty object relation."""
    if empty_spec is None:
        return
    if empty_spec.kind is TerminalObjectEmptyKind.OBJECT_NOT_FOUND:
        msg = f"{model_cls.__name__} with id {empty_spec.object_id} not found"
        raise ObjectNotFoundError(msg)
    if empty_spec.kind is TerminalObjectEmptyKind.VALUE_ERROR:
        raise ValueError(empty_spec.message or "Required row was not returned.")
    if empty_spec.kind is TerminalObjectEmptyKind.PROGRAMMING_ERROR:
        raise ProgrammingError(empty_spec.message or "Required row was not returned.")
    raise AssertionError(f"Unhandled terminal object empty behavior: {empty_spec.kind}")


def _materialize_terminal_object(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    from l2070_batching.post_op_domain_decoders import (
        decode_terminal_object_literal_payload,
        DECODE_NOT_HANDLED,
        materialize_domain_decoder,
    )
    from l2070_batching.post_op_structured import (
        decode_conditional_fired_labels,
        decode_structured_result,
    )

    if isinstance(spec.terminal_literal, LiteralResult):
        return spec.terminal_literal.value
    payload = _decoder_payload(spec)
    if spec.terminal_materializer is TerminalMaterializerKind.EXACT_SINGLE_ROW:
        if not raw:
            msg = "Exact single-row post-op received no rows."
            raise ValueError(msg)
        if len(raw) > 1:
            msg = f"Exact single-row post-op received {len(raw)} rows."
            raise ValueError(msg)
        return _row_dict(cast("Mapping[str, object]", raw[0]))
    if spec.terminal_materializer is TerminalMaterializerKind.REPLAY_LOOP_RESULT:
        if not raw:
            return None
        if len(raw) > 1:
            msg = f"Replay loop result post-op received {len(raw)} rows."
            raise ValueError(msg)
        row = _row_dict(cast("Mapping[str, object]", raw[0]))
        return row.get("value")
    if spec.structured_result is not None:
        return decode_structured_result(spec.structured_result, raw, hydrator)
    if spec.terminal_materializer is TerminalMaterializerKind.AUTH_TRACKED_TOKEN_VALIDATION:
        from impl.common.l2070_server_plan.steps.intent_auth_lazy import (
            materialize_auth_tracked_token_validation,
        )

        return materialize_auth_tracked_token_validation(spec.literal_payload, raw, hydrator)
    if spec.conditional_fired_labels is not None:
        return decode_conditional_fired_labels(spec.conditional_fired_labels, raw)
    if spec.domain_decoder is not None:
        return materialize_domain_decoder(spec.domain_decoder, raw, hydrator)
    if spec.terminal_materializer is TerminalMaterializerKind.PERMITTED_RAW_ROW and not raw:
        message = payload.get("error_message") if isinstance(payload, Mapping) else None
        raise DbPermissionError(str(message or "Permission denied."))

    literal_payload_result = decode_terminal_object_literal_payload(spec, raw, hydrator)
    if literal_payload_result is not DECODE_NOT_HANDLED:
        return literal_payload_result

    if isinstance(spec.terminal_literal, DecoderConfig):
        raise ValueError("DecoderConfig was not claimed by any closed literal-payload decoder")
    if spec.literal_payload is not None and not raw and spec.model_cls is None:
        return spec.literal_payload
    if spec.model_cls is not None and raw:
        for row in raw:
            if _maybe_row_dict(row) is None:
                msg = "Terminal model hydration requires final mapping rows."
                raise TypeError(msg)
    if spec.strict_one and len(raw) > 1:
        msg = f"Multiple results found: execute_one() returned more than one result ({len(raw)}+ rows)"
        raise ValueError(msg)
    if spec.inline_large_column_query_config is not None:
        from impl.common.l2070_server_plan.steps.large_column_read import (
            materialize_inline_large_column_query_result,
        )

        return materialize_inline_large_column_query_result(
            spec.inline_large_column_query_config,
            raw,
            hydrator,
        )
    if spec.blob_diff_block_size is not None:
        from impl.common.l2070_server_plan.steps.intent_diff_bytes import (
            _post_process_compute_blob_diff_row,
        )

        return _post_process_compute_blob_diff_row(raw, spec.blob_diff_block_size)
    if spec.two_way_diff_config is not None:
        from impl.common.l2070_server_plan.steps.intent_diff_revert import (
            materialize_two_way_diff_sql_rows,
        )

        return materialize_two_way_diff_sql_rows(spec.two_way_diff_config, raw)
    if spec.three_way_diff_config is not None:
        from impl.common.l2070_server_plan.steps.intent_diff_revert import (
            materialize_three_way_diff_sql_rows,
        )

        return materialize_three_way_diff_sql_rows(spec.three_way_diff_config, raw)
    if spec.unversioned_vector_scores_config is not None:
        from impl.common.l2070_server_plan.steps.intent_vector_query import (
            materialize_unversioned_vector_scores,
        )

        return materialize_unversioned_vector_scores(
            spec.unversioned_vector_scores_config,
            raw,
            hydrator,
        )
    if spec.terminal_materializer is TerminalMaterializerKind.PERMITTED_RAW_ROW:
        if not raw:
            message = payload.get("error_message") if isinstance(payload, Mapping) else None
            raise DbPermissionError(str(message or "Permission denied."))
        return _row_dict(cast("Mapping[str, object]", raw[0]))
    if spec.raw_mode:
        if not raw:
            if spec.terminal_materializer is TerminalMaterializerKind.REQUIRED_RAW_ROW:
                message = payload.get("empty_message") if isinstance(payload, Mapping) else None
                raise ValueError(str(message or "Required row was not returned."))
            return None
        raw_row = _rows_as_dicts(raw)[0]
        if spec.select_columns is not None:
            projected_row: dict[str, object] = {}
            for column in spec.select_columns:
                value = _projected_column_value(raw_row, column, spec.model_cls)
                projected_row[column] = None if value is _PROJECTED_COLUMN_MISSING else value
            raw_row = projected_row
        if spec.model_cls is not None:
            from impl.common.l5200_sql_query.row_converter import (
                coerce_raw_row_to_model_field_types,
            )

            return coerce_raw_row_to_model_field_types(spec.model_cls, raw_row)
        return raw_row
    if spec.columns:
        if not raw:
            return None
        row_dict = _row_dict(cast("Mapping[str, object]", raw[0]))
        if spec.model_cls is not None:
            from impl.common.l5200_sql_query.row_converter import convert_row_to_model

            return convert_row_to_model(
                spec.model_cls,
                row_dict,
                select_columns=[str(column) for column in spec.columns],
            )
        row_values = tuple(row_dict.values())
        values: list[object] = []
        for idx, column in enumerate(spec.columns):
            value = _projected_column_value(row_dict, column, spec.model_cls)
            if value is _PROJECTED_COLUMN_MISSING:
                value = row_values[idx] if idx < len(row_values) else None
            values.append(value)
        return values[0] if len(values) == 1 else tuple(values)
    if spec.model_cls is not None:
        if spec.model_cls is None:
            msg = "HYDRATE_ONE materialization requires a model class."
            raise ValueError(msg)
        from impl.common.l2070_server_plan.steps.row_hydration import _hydrate_row

        empty_spec = spec.terminal_object_empty
        if not raw:
            _raise_terminal_object_empty(empty_spec, spec.model_cls)
            return None
        row_dict = _row_dict(_require_row(raw, spec.row_index))
        if not row_dict:
            return None
        data_values = [value for key, value in row_dict.items() if not key.startswith("__")]
        if data_values and all(value is None for value in data_values):
            _raise_terminal_object_empty(empty_spec, spec.model_cls)
            return None
        if "sys_id" in row_dict and row_dict["sys_id"] is None:
            _raise_terminal_object_empty(empty_spec, spec.model_cls)
            return None
        from l1000_schema.column_utils import get_db_column_name

        model_payload_columns = {field_name for field_name in spec.model_cls.model_fields if row_dict.get(field_name) is not None}
        model_payload_columns.update(
            field_name
            for field_name in spec.model_cls.model_fields
            if row_dict.get(get_db_column_name(spec.model_cls, DynamicFieldName(field_name))) is not None
        )
        if not model_payload_columns:
            _raise_terminal_object_empty(empty_spec, spec.model_cls)
            return None
        return _hydrate_row(spec.model_cls, row_dict, hydrator)
    if isinstance(spec.target_type, type) and is_dataclass(spec.target_type):
        from l2070_batching.post_op_structured import decode_dataclass_one

        return decode_dataclass_one(spec.target_type, raw)
    if spec.result_cls is not None:
        return _materialize_hydrate_dict_one(spec, raw)
    msg = (
        "Terminal object post-op requires an explicit closed decoder, structured result, "
        "raw_mode, model_cls, columns, target_type, result_cls, or typed materialization config."
    )
    raise ProgrammingError(msg)


def _materialize_terminal_array(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    from l2070_batching.post_op_domain_decoders import (
        decode_terminal_array_literal_payload,
        DECODE_NOT_HANDLED,
        materialize_domain_decoder,
    )
    from l2070_batching.post_op_structured import (
        decode_compound_result,
        decode_revision_cache_tags,
        decode_structured_array,
    )

    if isinstance(spec.terminal_literal, LiteralResult):
        return spec.terminal_literal.value
    if spec.compound_result is not None:
        return decode_compound_result(spec.compound_result, raw, hydrator)
    if spec.structured_array is not None:
        return decode_structured_array(spec.structured_array, raw, hydrator)
    if spec.revision_cache_tags is not None:
        return decode_revision_cache_tags(spec.revision_cache_tags, raw)
    if spec.domain_decoder is not None:
        return materialize_domain_decoder(spec.domain_decoder, raw, hydrator)

    literal_payload_result = decode_terminal_array_literal_payload(spec, raw)
    if literal_payload_result is not DECODE_NOT_HANDLED:
        return literal_payload_result
    if spec.column is not None and spec.model_cls is None:
        values: list[object] = []
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            if spec.column in row_dict:
                value = _coerce_scalar(row_dict[spec.column], spec.scalar_coercion)
                if value is not None and spec.target_type is not None:
                    value = spec.target_type(value)
                values.append(value)
        if spec.result_cls is frozenset:
            return frozenset(values)
        if spec.result_cls is set:
            return set(values)
        if spec.result_cls is tuple:
            return tuple(values)
        return values
    if spec.embedding_worker_dispatch_groups:
        from impl.common.l2070_server_plan.steps.embedding_worker_sql_orchestration import (
            _embedding_worker_groups_from_rows,
        )

        return _embedding_worker_groups_from_rows(raw, hydrator)
    if spec.vector_search_results_config is not None:
        from impl.common.l2070_server_plan.steps.intent_vector_query import (
            materialize_vector_search_results,
        )

        return materialize_vector_search_results(
            spec.vector_search_results_config,
            raw,
            hydrator,
        )
    if spec.vector_search_id_scores_config is not None:
        from impl.common.l2070_server_plan.steps.intent_vector_query import (
            materialize_vector_search_id_scores,
        )

        return materialize_vector_search_id_scores(
            spec.vector_search_id_scores_config,
            raw,
            hydrator,
        )
    if spec.column is not None:
        values = _materialize_scalar_column_list(spec, raw)
        if spec.result_cls is frozenset:
            return frozenset(values)
        if spec.result_cls is set:
            return set(values)
        return values
    if spec.result_cls is not None:
        return _materialize_hydrate_dict_many(spec, raw)
    if spec.raw_mode:
        raw_rows = _rows_as_dicts(raw)
        if not raw_rows and spec.empty_rows_exception is not None:
            raise spec.empty_rows_exception(spec.error_message or "Required result rows are absent")
        if spec.select_columns is not None:
            projected_rows: list[dict[str, object]] = []
            for row in raw_rows:
                projected_row: dict[str, object] = {}
                for column in spec.select_columns:
                    value = _projected_column_value(row, column, spec.model_cls)
                    projected_row[column] = None if value is _PROJECTED_COLUMN_MISSING else value
                projected_rows.append(projected_row)
            raw_rows = projected_rows
        if spec.model_cls is not None:
            from impl.common.l5200_sql_query.row_converter import (
                coerce_raw_row_to_model_field_types,
            )

            return [coerce_raw_row_to_model_field_types(spec.model_cls, row) for row in raw_rows]
        return raw_rows
    if spec.columns:
        rows: list[object] = []
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            if spec.model_cls is not None:
                from impl.common.l5200_sql_query.row_converter import convert_row_to_model

                rows.append(
                    convert_row_to_model(
                        spec.model_cls,
                        row_dict,
                        select_columns=[str(column) for column in spec.columns],
                    ),
                )
                continue
            row_values = tuple(row_dict.values())
            row_values_for_columns: list[object] = []
            for idx, column in enumerate(spec.columns):
                value = _projected_column_value(row_dict, column, spec.model_cls)
                if value is _PROJECTED_COLUMN_MISSING:
                    value = row_values[idx] if idx < len(row_values) else None
                row_values_for_columns.append(value)
            rows.append(row_values_for_columns[0] if len(row_values_for_columns) == 1 else tuple(row_values_for_columns))
        return rows
    if (
        spec.model_cls is not None
        and len(raw) == 1
        and isinstance(raw[0], Mapping)
        and set(raw[0]) in ({"value"}, {"__executor_value__"})
    ):
        envelope_column = next(iter(raw[0]))
        value = raw[0][envelope_column]
        if not isinstance(value, list):
            value = None
        if isinstance(value, list) and all(isinstance(item, spec.model_cls) for item in value):
            return value
    if spec.model_cls is not None:
        if spec.raw_mode:
            return _rows_as_dicts(raw)
        from impl.common.l2070_server_plan.steps.row_hydration import _hydrate_row
        from impl.common.l5200_sql_query.row_converter import convert_row_to_model

        materialized: list[object] = []
        model_rows: list[dict[str, Any]] = []
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            if "sys_id" in row_dict:
                if row_dict["sys_id"] is None:
                    continue
            else:
                data_values = [value for key, value in row_dict.items() if not key.startswith("__")]
                if data_values and all(value is None for value in data_values):
                    continue
            model_rows.append(row_dict)
        if spec.select_columns is None:
            from l2070_batching.hydrator import MaterializationHydrator

            if isinstance(hydrator, MaterializationHydrator):
                batch = hydrator.hydrate_models(spec.model_cls, model_rows)
                if batch is not None:
                    return batch
        for row_dict in model_rows:
            if spec.select_columns is not None:
                materialized.append(
                    convert_row_to_model(
                        spec.model_cls,
                        row_dict,
                        select_columns=list(spec.select_columns),
                        hydrate_large_columns=False,
                    ),
                )
            else:
                materialized.append(_hydrate_row(spec.model_cls, row_dict, hydrator))
        return materialized
    msg = (
        "Terminal array post-op requires an explicit closed decoder, raw_mode, model_cls, "
        "columns, result_cls, column projection, or typed materialization config."
    )
    raise ProgrammingError(msg)


def _materialize_by_post_op_behavior(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    if spec.domain_decoder is not None:
        from l2070_batching.post_op_domain_decoders import materialize_domain_decoder

        return materialize_domain_decoder(spec.domain_decoder, raw, hydrator)
    if spec.behavior is PostOpBehavior.EXCEPTION_ONLY:
        if spec.assertion_from_row is not None:
            _materialize_assertion_from_row(spec.assertion_from_row, raw)
            return None
        if not raw:
            return None
        if isinstance(spec.literal_payload, Mapping) and "message" in spec.literal_payload:
            raise ValueError(str(spec.literal_payload.get("message") or "SQL assertion failed"))
        assert_result(
            ResultAssertionSpec(
                mappings=(
                    AssertionExceptionMapping(
                        code=AssertionResultCode.ERROR,
                        exc_type=ProgrammingError,
                        default_message=spec.error_message or "Compiled exception-only post-op failed.",
                    ),
                    AssertionExceptionMapping(
                        code=AssertionResultCode.POLICY_DENIED,
                        exc_type=DbPermissionError,
                        default_message=spec.error_message or "Permission denied.",
                    ),
                    AssertionExceptionMapping(
                        code=AssertionResultCode.NOT_FOUND,
                        exc_type=ObjectNotFoundError,
                        default_message=spec.error_message or "Object not found.",
                    ),
                ),
            ),
            raw,
        )
        return None
    if spec.tuple_query_projection_config is not None:
        from l2060_query_builder.tuple_query import materialize_tuple_query_builder_from_rows

        return materialize_tuple_query_builder_from_rows(
            spec.tuple_query_projection_config,
            cast("Sequence[Any]", raw),
        )
    if spec.behavior is PostOpBehavior.TERMINAL_SCALAR:
        return _materialize_terminal_scalar(spec, raw)
    if spec.behavior is PostOpBehavior.TERMINAL_OBJECT:
        return _materialize_terminal_object(spec, raw, hydrator)
    if spec.behavior is PostOpBehavior.TERMINAL_ARRAY:
        return _materialize_terminal_array(spec, raw, hydrator)
    if spec.behavior is PostOpBehavior.EXCEPTION_ONLY:
        if spec.assertion_from_row is not None:
            _materialize_assertion_from_row(spec.assertion_from_row, raw)
            return None
        if not raw:
            return None
        raise ValueError(spec.error_message or "SQL assertion failed")
    msg = f"Unsupported post-op behavior for result materialization: {spec.behavior}"
    raise ValueError(msg)


def _raise_runtime_assertion_exception(exc_type: type[Any], message: str) -> None:
    try:
        raise exc_type(message)
    except TypeError as positional_error:
        try:
            raise exc_type(message=message) from None
        except TypeError:
            raise positional_error


def materialize_result(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Materialize a final Python result from interpreter-authorized rows."""

    require_post_op_interpreter_authority(operation="materialize_result")
    return _materialize_by_post_op_behavior(spec, raw, hydrator)


def _assert_publication_proof(spec: PublicationProofAssertionSpec, raw: RawResult) -> None:
    from impl.common.l2070_server_plan.publication_speculation_proof import (
        PublicationProofDriverRow,
        decode_publication_proof_frame,
    )
    from impl.common.l2070_server_plan.steps.commit_branch_steps import SpeculativePublicationFactsMiss

    driver_rows = tuple(PublicationProofDriverRow.model_validate(_require_row(raw, index)) for index in range(len(raw)))
    domain_rows = tuple(row.domain_row() for row in driver_rows)
    frame = decode_publication_proof_frame(
        domain_rows,
        expected_scope_id=spec.scope_id,
        expected_attempt_id=spec.attempt_id,
    )
    if not frame.admitted:
        raise SpeculativePublicationFactsMiss(frame)


def _assert_branch_route_proof(spec: BranchRouteProofAssertionSpec, raw: RawResult) -> None:
    from impl.common.l2070_server_plan.branch_route_speculation import (
        BranchRouteSpeculationMiss,
        decode_branch_route_proof_frame,
    )

    frame = decode_branch_route_proof_frame(
        tuple(_require_row(raw, index) for index in range(len(raw))),
        expected_scope_id=spec.scope_id,
        expected_attempt_id=spec.attempt_id,
        expected_intent_ids=frozenset(spec.intent_ids),
    )
    if not frame.admitted:
        raise BranchRouteSpeculationMiss(frame)


def assert_result(spec: ResultAssertionSpec, raw: RawResult) -> None:
    """Raise from an interpreter-authorized closed assertion result."""

    require_post_op_interpreter_authority(operation="assert_result")
    if spec.publication_proof is not None:
        _assert_publication_proof(spec.publication_proof, raw)
        return None
    if spec.branch_route_proof is not None:
        _assert_branch_route_proof(spec.branch_route_proof, raw)
        return None
    if spec.static_exception is not None:
        if spec.static_exception_requires_row and not raw:
            return None
        raise spec.static_exception(spec.static_message or "")
    if not raw:
        if spec.allow_empty_result:
            return None
        for mapping in spec.mappings:
            if mapping.code is spec.empty_result_code:
                raise mapping.exc_type(mapping.default_message)
        raise RuntimeError("Compiled assertion returned no rows.")
    for row_index in range(len(raw)):
        row = _require_row(raw, row_index)
        if spec.ok_column not in row:
            raise RuntimeError(f"Compiled assertion result is missing column {spec.ok_column!r}.")
        ok_value = row.get(spec.ok_column)
        if bool(ok_value):
            continue
        raw_code = row.get(spec.error_code_column)
        code = AssertionResultCode.ERROR
        if isinstance(raw_code, AssertionResultCode):
            code = raw_code
        elif isinstance(raw_code, str):
            try:
                code = AssertionResultCode(raw_code)
            except ValueError:
                code = AssertionResultCode.ERROR
        message = row.get(spec.message_column)
        message_text = message if isinstance(message, str) and message else None
        for mapping in spec.mappings:
            if mapping.code is code:
                raise mapping.exc_type(message_text or mapping.default_message)
        raise RuntimeError(message_text or "Compiled assertion failed.")
    return None


def _assert_designed_materialization_spec(spec: ResultMaterializationSpec) -> None:
    """Reject known relation transformations before legacy materializer dispatch."""

    if spec.raw_mode and spec.model_cls is not None:
        raise IllegalMaterializationExecution(
            "post_op.relation_shape_mutation: relation semantics must be declared by the producer's final SQL relation.",
        )


def domain_post_op_runtime_symbol(kind: DomainPostOpDecoderKind) -> PostOpRuntimeSymbol:
    """Return the exact signed runtime symbol for one closed domain decoder."""

    return PostOpRuntimeSymbol(f"decoder.DomainPostOpDecoderKind.{kind.name}")


def post_op_runtime_symbol(spec: ResultMaterializationSpec | ResultAssertionSpec) -> str:
    """Return the exact operation selected by a closed post-op specification."""

    if isinstance(spec, ResultAssertionSpec):
        return "assertion.result"
    if spec.domain_decoder is not None:
        return domain_post_op_runtime_symbol(spec.domain_decoder.kind)
    if spec.tuple_query_projection_config is not None:
        return "materializer.tuple_query_projection"
    if spec.behavior is PostOpBehavior.EXCEPTION_ONLY:
        if spec.assertion_from_row is not None:
            if spec.assertion_from_row.kind is RowAssertionKind.VECTOR_DIMENSION_VALIDATION:
                return "assertion.row.vector_dimension_validation"
            raise AssertionError(f"Unhandled row assertion kind: {spec.assertion_from_row.kind}")
        return "assertion.exception_row"
    if spec.behavior is PostOpBehavior.TERMINAL_SCALAR:
        if spec.scalar_tuple is not None:
            return "materializer.scalar_tuple"
        if spec.scalar_row_value is not None:
            if spec.scalar_row_value.kind is ScalarRowValueKind.DELETED_COUNT_BOOL:
                return "materializer.scalar_row.deleted_count_bool"
            raise AssertionError(f"Unhandled scalar row kind: {spec.scalar_row_value.kind}")
        if spec.column is None and not spec.first_row_scalar:
            return "materializer.row_count"
        return "materializer.scalar_column"
    if isinstance(spec.terminal_literal, LiteralResult):
        return "materializer.literal"
    if spec.behavior is PostOpBehavior.TERMINAL_OBJECT:
        if spec.structured_result is not None:
            return "materializer.structured_object"
        if spec.terminal_materializer is TerminalMaterializerKind.AUTH_TRACKED_TOKEN_VALIDATION:
            return "materializer.auth_tracked_token_validation"
        if spec.conditional_fired_labels is not None:
            return "materializer.conditional_fired_labels"
        if spec.inline_large_column_query_config is not None:
            return "materializer.inline_large_column"
        if spec.blob_diff_block_size is not None:
            return "materializer.blob_diff"
        if spec.two_way_diff_config is not None:
            return "materializer.two_way_diff"
        if spec.three_way_diff_config is not None:
            return "materializer.three_way_diff"
        if spec.unversioned_vector_scores_config is not None:
            return "materializer.unversioned_vector_scores"
        if spec.raw_mode:
            if spec.terminal_materializer is TerminalMaterializerKind.PERMITTED_RAW_ROW:
                return "materializer.permitted_raw_row"
            if spec.terminal_materializer is TerminalMaterializerKind.REQUIRED_RAW_ROW:
                return "materializer.required_raw_row"
            if spec.terminal_materializer is TerminalMaterializerKind.EXACT_SINGLE_ROW:
                return "materializer.object_payload.exact_single_row"
            return "materializer.raw_row"
        if spec.columns:
            return "materializer.projected_model_one" if spec.model_cls is not None else "materializer.projected_row_one"
        if spec.model_cls is not None:
            if spec.terminal_object_empty is not None:
                if spec.terminal_object_empty.kind is TerminalObjectEmptyKind.OBJECT_NOT_FOUND:
                    return "materializer.model_one_empty.object_not_found"
                if spec.terminal_object_empty.kind is TerminalObjectEmptyKind.PROGRAMMING_ERROR:
                    return "materializer.model_one_empty.programming_error"
                if spec.terminal_object_empty.kind is TerminalObjectEmptyKind.VALUE_ERROR:
                    return "materializer.model_one_empty.value_error"
                raise AssertionError(f"Unhandled terminal object empty kind: {spec.terminal_object_empty.kind}")
            return "materializer.HydrateFirstResolvedRowStep.model_one"
        if isinstance(spec.target_type, type) and is_dataclass(spec.target_type):
            return "materializer.dataclass_one"
        if spec.result_cls is not None:
            return "materializer.result_class_one"
        if spec.terminal_materializer is TerminalMaterializerKind.REPLAY_LOOP_RESULT:
            return "materializer.object_payload.replay_loop_result"
        if spec.terminal_materializer is TerminalMaterializerKind.EMBEDDING_REQUIRE_NO_ROWS:
            return "materializer.object_payload.embedding_require_no_rows"
        if spec.terminal_materializer is TerminalMaterializerKind.CACHE_GET_RESOLUTION:
            return "materializer.object_payload.cache_get_resolution"
        if spec.literal_payload is not None:
            msg = (
                "Post-op specification does not select one exact signed runtime operation. "
                "Use terminal_literal for data or select a closed decoder."
            )
            raise ProgrammingError(msg)
    if spec.behavior is PostOpBehavior.TERMINAL_ARRAY:
        if spec.compound_result is not None:
            return "materializer.compound_array"
        if spec.structured_array is not None:
            return "materializer.structured_array"
        if spec.revision_cache_tags is not None:
            return "materializer.revision_cache_tags"
        if spec.column is not None:
            if spec.result_cls is frozenset:
                return "materializer.scalar_column_frozenset"
            if spec.result_cls is set:
                return "materializer.scalar_column_set"
            if spec.result_cls is tuple:
                return "materializer.scalar_column_tuple"
            return "materializer.scalar_column_list"
        if spec.embedding_worker_dispatch_groups:
            return "materializer.embedding_worker_dispatch_groups"
        if spec.vector_search_results_config is not None:
            return "materializer.vector_search_results"
        if spec.vector_search_id_scores_config is not None:
            return "materializer.vector_search_id_scores"
        if spec.result_cls is not None:
            return "materializer.result_class_many"
        if spec.raw_mode:
            return "materializer.raw_rows"
        if spec.columns:
            return "materializer.projected_model_many" if spec.model_cls is not None else "materializer.projected_rows"
        if spec.model_cls is not None:
            return "materializer.HydrateResolvedRowsStep.model_many"
        if spec.terminal_materializer is TerminalMaterializerKind.GRAPH_BINDINGS:
            return "materializer.array_payload.graph_bindings"
        if spec.terminal_materializer is TerminalMaterializerKind.SEARCH_WITH_META:
            return "materializer.array_payload.search_with_meta"
        if spec.terminal_materializer is TerminalMaterializerKind.DOLT_MATERIALIZED_REVISION_IDS:
            return "materializer.array_payload.dolt_materialized_revision_ids"
        if spec.terminal_materializer is TerminalMaterializerKind.MATERIALIZATION_CANDIDATES:
            return "materializer.array_payload.materialization_candidates"
    msg = (
        "Post-op specification does not select one exact signed runtime operation. "
        "Use terminal_literal for data or select a closed decoder."
    )
    raise ProgrammingError(msg)


def materialize_compiled_post_op(
    post_op: CompiledPostOp,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Interpret a closed compiled post-op from executor-produced raw rows only."""

    # Runtime refs are deliberately not a parameter here. They are executor-owned
    # step dependencies; making them visible to post-ops reopens hidden runtime
    # dataflow outside the signed post-op surface.
    from l2070_batching.hydrator import capability_free_materialization_hydrator

    materialization_hydrator = capability_free_materialization_hydrator(hydrator)
    with post_op_interpreter_scope():
        if post_op.kind is PostOpKind.MATERIALIZE_RESULT:
            result_spec = cast("ResultMaterializationSpec", post_op.spec)
            assert result_spec.behavior is not None
            _assert_designed_materialization_spec(result_spec)
            assert_post_op_symbol_signed(post_op.runtime_symbol)
            if result_spec.domain_decoder is not None:
                from l2070_batching.post_op_domain_decoders import materialize_domain_decoder

                return materialize_domain_decoder(
                    result_spec.domain_decoder,
                    raw,
                    materialization_hydrator,
                )
            return materialize_result(
                result_spec,
                raw,
                materialization_hydrator,
            )
        if post_op.kind is PostOpKind.ASSERT_RESULT:
            assert_post_op_symbol_signed(post_op.runtime_symbol)
            assert_result(cast("ResultAssertionSpec", post_op.spec), raw)
            return None
        msg = f"Unsupported compiled post-op kind: {post_op.kind.value}"
        raise ValueError(msg)

