# This module defines the signed post-op surface. Do not add runtime-ref based
# specs here: runtime refs are executor-owned ServerPlan dependencies, not
# terminal post-op materialization inputs.
class PostOpKind(StrEnum):
    """Closed executor-interpreted post-processing operation kinds."""

    MATERIALIZE_RESULT = "materialize_result"
    ASSERT_RESULT = "assert_result"


