    column_names: tuple[SqlColumnName, ...]
    default_values: tuple[object, ...]
    return_none_on_empty: bool = False

    def __post_init__(self: ScalarTupleResultSpec) -> None:
        if len(self.column_names) != len(self.default_values):
            msg = "ScalarTupleResultSpec requires one default per column."
            raise ValueError(msg)


@dataclass(frozen=True, slots=True)
