def _runtime_builder_value_is_compiled_post_op(value: object) -> bool:
    from l2070_batching.post_op import CompiledPostOp

    return isinstance(value, CompiledPostOp)


def _runtime_builder_value_is_callable_escape(value: object) -> bool:
    if isinstance(value, type):
        return False
    if _runtime_builder_value_is_compiled_post_op(value):
        return False
    return isinstance(value, FunctionType | BuiltinFunctionType | MethodType | partial) or callable(value)


def _runtime_builder_value_is_scalar_data(value: object) -> bool:
    return isinstance(value, _RUNTIME_BUILDER_SCALAR_TYPES)


def _runtime_builder_value_is_sql_grammar_object(value: object) -> bool:
    from impl.common.l2100_sql_grammar.base import SqlRenderable

    return isinstance(value, SqlRenderable)


def _runtime_builder_value_is_plan_handle(value: object) -> bool:
    from l7200_versioned_transactions.graph_lazy_sql import SqlPlanGraphQuery

    return isinstance(value, SqlPlanGraphQuery)


def _runtime_builder_value_is_runtime_state_carrier(value: object) -> bool:
    if _runtime_builder_value_is_scalar_data(value):
        return False
    if isinstance(value, type):
        return False
    return any(callable(getattr(value, attr, None)) for attr in _RUNTIME_STATE_CARRIER_ATTRS)


def _assert_runtime_builder_key_value_allowed(
    key: str,
    value: object,
    *,
    path: str,
) -> None:
    lowered_key = key.lower()
    if lowered_key in _RUNTIME_BUILDER_FORBIDDEN_LITERAL_KEY_NAMES:
        if _runtime_builder_value_is_scalar_data(value):
            return
        if _runtime_builder_value_is_runtime_state_carrier(value):
            msg = f"{path} carries a runtime state object."
            raise TypeError(msg)
        msg = f"{path} is an opaque behavior carrier."
        raise ValueError(msg)
    if any(part in lowered_key for part in _RUNTIME_BUILDER_FORBIDDEN_LITERAL_KEY_PARTS):
        msg = f"{path} is an opaque behavior carrier."
        raise ValueError(msg)


def _assert_no_runtime_behavior_escape(
    value: object,
    *,
    path: str,
    visited: set[int] | None = None,
    allow_pydantic_models: bool = False,
) -> None:
    if visited is None:
        visited = set()
    if _runtime_builder_value_is_scalar_data(value):
        return
    if allow_pydantic_models and isinstance(value, BaseModel):
        return
    if isinstance(value, EmptyDomainDecoderPayload):
        return
    if isinstance(
        value,
        ResultMaterializationSpec | ResultAssertionSpec,
    ):
        return
    if _runtime_builder_value_is_callable_escape(value):
        msg = f"{path} carries a callable value."
        raise TypeError(msg)
    if _runtime_builder_value_is_plan_handle(value):
        msg = f"{path} carries a compile-time plan handle."
        raise TypeError(msg)
    if _runtime_builder_value_is_sql_grammar_object(value):
        msg = f"{path} carries unsupported runtime builder payload {type(value).__name__}."
        raise TypeError(msg)
    if _runtime_builder_value_is_runtime_state_carrier(value):
        msg = f"{path} carries a runtime state object."
        raise TypeError(msg)
    value_id = id(value)
    if value_id in visited:
        return
    visited.add(value_id)
    if isinstance(value, Mapping):
        for key, item in value.items():
            key_text = str(key)
            _assert_runtime_builder_key_value_allowed(
                key_text,
                item,
                path=f"{path}.{key_text}",
            )
            if _COMMON_RUNTIME_PAYLOAD_SCHEMA.allows_declared_field(key_text, item):
                continue
            _assert_no_runtime_behavior_escape(
                item,
                path=f"{path}.{key_text}",
                visited=visited,
                allow_pydantic_models=allow_pydantic_models,
            )
        return
    if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
        for index, item in enumerate(value):
            _assert_no_runtime_behavior_escape(
                item,
                path=f"{path}[{index}]",
                visited=visited,
                allow_pydantic_models=allow_pydantic_models,
            )
        return
    if isinstance(value, set | frozenset):
        for index, item in enumerate(sorted(value, key=repr)):
            _assert_no_runtime_behavior_escape(
                item,
                path=f"{path}[{index}]",
                visited=visited,
                allow_pydantic_models=allow_pydantic_models,
            )
        return
    if is_dataclass(value) and not isinstance(value, type):
        for field_info in fields(value):
            item = getattr(value, field_info.name)
            _assert_runtime_builder_key_value_allowed(
                field_info.name,
                item,
                path=f"{path}.{field_info.name}",
            )
            if _COMMON_RUNTIME_PAYLOAD_SCHEMA.allows_declared_field(field_info.name, item):
                continue
            _assert_no_runtime_behavior_escape(
                item,
                path=f"{path}.{field_info.name}",
                visited=visited,
                allow_pydantic_models=allow_pydantic_models,
            )
        return
    msg = f"{path} carries unsupported runtime builder payload {type(value).__name__}."
    raise TypeError(msg)


@dataclass(frozen=True, slots=True)
class AssertionExceptionMapping:
    """Map one SQL-produced assertion code to a typed exception."""

    code: AssertionResultCode
    exc_type: type[Exception]
    default_message: str


@dataclass(frozen=True, slots=True)
class PublicationProofAssertionSpec:
    """Bind one typed publication proof relation to its compiled attempt."""

    scope_id: SpeculationScopeId
    attempt_id: SpeculationAttemptId

    def __post_init__(self: PublicationProofAssertionSpec) -> None:
        if not self.scope_id:
            raise ValueError("A publication proof assertion requires a scope identity")
        if self.attempt_id < 0:
            raise ValueError("A publication proof assertion attempt cannot be negative")


@dataclass(frozen=True, slots=True)
class BranchRouteProofAssertionSpec:
    """Bind one typed branch-route proof relation to its compiled attempt."""

    scope_id: SpeculationScopeId
    attempt_id: SpeculationAttemptId
    intent_ids: tuple[SpeculationIntentId, ...]

    def __post_init__(self: BranchRouteProofAssertionSpec) -> None:
        if not self.scope_id:
            raise ValueError("A branch-route proof assertion requires a scope identity")
        if self.attempt_id < 0:
            raise ValueError("A branch-route proof assertion attempt cannot be negative")
        if not self.intent_ids or len(set(self.intent_ids)) != len(self.intent_ids):
            raise ValueError("A branch-route proof assertion requires unique intent identities")


@dataclass(frozen=True, slots=True)
class ResultAssertionSpec:
    """Declarative assertion spec interpreted after SQL/IR execution."""

    publication_proof: PublicationProofAssertionSpec | None = None
    branch_route_proof: BranchRouteProofAssertionSpec | None = None
    ok_column: str = "ok"
    error_code_column: str = "error_code"
    message_column: str = "message"
    mappings: tuple[AssertionExceptionMapping, ...] = ()
    static_exception: type[Exception] | None = None
    static_message: str | None = None
    static_exception_requires_row: bool = False
    allow_empty_result: bool = False
    empty_result_code: AssertionResultCode = AssertionResultCode.ERROR

