DECODE_NOT_HANDLED = object()


def _staged_commit_id_values(value: object) -> tuple[object, ...]:
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return tuple(value)
    text = str(value)
    if text.startswith("JSON(") and text.endswith(")"):
        text = text.removeprefix("JSON(").removesuffix(")")
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError):
        return ()
    if isinstance(parsed, Sequence) and not isinstance(parsed, (str, bytes)):
        return tuple(parsed)
    return ()


def _expect_payload[T](spec: DomainPostOpDecoderSpec, payload_type: type[T]) -> T:
    payload = spec.payload
    if not isinstance(payload, payload_type):
        msg = f"{spec.kind.value} expected payload {payload_type.__name__}, got {type(payload).__name__}."
        raise TypeError(msg)
    return payload


def _expect_empty_payload(spec: DomainPostOpDecoderSpec) -> None:
    if spec.payload is not None:
        msg = f"{spec.kind.value} does not accept a payload."
        raise TypeError(msg)


def _int_value(value: object) -> int:
    return int(cast("int | float | str | bytes", value))


def materialize_domain_decoder(
    spec: DomainPostOpDecoderSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Dispatch one closed domain decoder to its typed implementation."""

    require_post_op_interpreter_authority(operation="materialize_domain_decoder")
    if spec.kind is DomainPostOpDecoderKind.BRANCH_ROUTE_PROOF:
        proof_spec = _expect_payload(spec, BranchRouteProofDecoderSpec)
        from impl.common.l2070_server_plan.branch_route_speculation import (
            BranchRouteSpeculationMiss,
            decode_branch_route_proof_frame,
        )

        if not raw:
            raise ValueError("Persisted branch route proof rejected the selected branch or revision")
        frame = decode_branch_route_proof_frame(
            tuple(_require_row(raw, index) for index in range(len(raw))),
            expected_scope_id=proof_spec.scope_id,
            expected_attempt_id=proof_spec.attempt_id,
            expected_intent_ids=frozenset(proof_spec.intent_ids),
        )
        if not frame.admitted:
            raise BranchRouteSpeculationMiss(frame)
        return frame
    if spec.kind is DomainPostOpDecoderKind.GRAPH_PATH_EVIDENCE:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_graph import (
            _process_graph_path_evidence_rows,
        )

        return _process_graph_path_evidence_rows(list(raw))
    if spec.kind is DomainPostOpDecoderKind.GRAPH_RESULT:
        graph_payload = _expect_payload(spec, GraphResultDecoderSpec)
        from impl.common.l2070_server_plan.steps.intent_graph import _process_graph_result_rows
        from l9600_graphs.graph import GraphEdge, GraphNode

        if not (isinstance(graph_payload.node_type, type) and issubclass(graph_payload.node_type, GraphNode)):
            msg = f"graph_result decoder requires a GraphNode class, got {graph_payload.node_type!r}"
            raise TypeError(msg)
        if not (isinstance(graph_payload.edge_type, type) and issubclass(graph_payload.edge_type, GraphEdge)):
            msg = f"graph_result decoder requires a GraphEdge class, got {graph_payload.edge_type!r}"
            raise TypeError(msg)
        return _process_graph_result_rows(
            list(raw),
            graph_payload.node_type,
            graph_payload.edge_type,
            entity_kind_column=str(graph_payload.entity_kind_column),
            entity_id_column=str(graph_payload.entity_id_column),
            node_prefix=str(graph_payload.node_prefix),
            edge_prefix=str(graph_payload.edge_prefix),
            node_columns=tuple(str(column) for column in graph_payload.node_columns),
            edge_columns=tuple(str(column) for column in graph_payload.edge_columns),
        )
    if spec.kind is DomainPostOpDecoderKind.COMMIT_BRANCH_CONTEXT:
        _expect_payload(spec, CommitBranchContextSpec)
        return decode_commit_branch_context(raw)
    if spec.kind is DomainPostOpDecoderKind.COMMIT_BRANCH_FETCH:
        return decode_commit_branch_fetch(_expect_payload(spec, CommitBranchFetchSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.CONTENT_STORE_ROW_LOOKUP:
        payload = spec.payload
        if isinstance(payload, ContentStoreRowLookupDecoderSpec):
            return decode_content_store_row_lookup(
                ContentStoreRowLookupSpec(payload.ref_id, payload.row_codec_kind),
                raw,
            )
        return decode_content_store_row_lookup(_expect_payload(spec, ContentStoreRowLookupSpec), raw)
    if spec.kind in {DomainPostOpDecoderKind.HISTORY_ENTRIES, DomainPostOpDecoderKind.HISTORY_ENTRIES_WITH_META}:
        payload = spec.payload
        if isinstance(payload, HistoryEntriesDecoderSpec):
            return decode_history_entries(
                HistoryEntriesSpec(payload.model_cls, payload.revision_model_cls),
                raw,
                hydrator,
            )
        return decode_history_entries(_expect_payload(spec, HistoryEntriesSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.HISTORY_CURSOR_PAGE:
        return decode_history_cursor_page(_expect_payload(spec, HistoryCursorPageSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.BRANCH_HISTORY_CURSOR_PAGE:
        return decode_branch_history_cursor_page(
            _expect_payload(spec, BranchHistoryCursorPageDecoderSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.PLAN_HISTORY_CURSOR_PAGE:
        return decode_plan_history_cursor_page(
            _expect_payload(spec, PlanHistoryCursorPageDecoderSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.TABLE_EXISTS_MANY:
        payload = spec.payload
        if isinstance(payload, TableExistsManyDecoderSpec):
            return decode_table_exists_many(
                TableExistsManySpec(payload.known_results, payload.unknown_names, payload.result_columns),
                raw,
            )
        return decode_table_exists_many(_expect_payload(spec, TableExistsManySpec), raw)
    if spec.kind is DomainPostOpDecoderKind.SCHEMA_STATE_SNAPSHOT:
        payload = _expect_payload(spec, SchemaStateSnapshotDecoderSpec)
        from impl.common.l2070_server_plan.steps.bootstrap_interrogation import (
            decode_reconciliation_interrogation_rows,
        )

        return decode_reconciliation_interrogation_rows(
            raw,
            root_ref=payload.root_ref,
            observed_trigger_tables=payload.observed_trigger_tables,
        )
    if spec.kind is DomainPostOpDecoderKind.VERSIONED_READ_CONTEXT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_versioned_read_context(raw)
    if spec.kind is DomainPostOpDecoderKind.VERSIONED_WRITE_BRANCH_CONTEXT:
        # Keep dependency refs typed through decoder payloads.
        payload = _expect_payload(spec, VersionedWriteBranchContextSpec)
        return decode_versioned_write_branch_context(payload, raw)
    if spec.kind is DomainPostOpDecoderKind.BRANCH_INFO:
        return decode_branch_info(_expect_payload(spec, BranchInfoSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.BRANCH_INFO_WITH_CREATED:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_branch_info(BranchInfoSpec(include_created=True), raw)
    if spec.kind is DomainPostOpDecoderKind.DELETED_COUNT:
        _expect_payload(spec, DeletedCountSpec)
        return decode_deleted_count(raw)
    if spec.kind is DomainPostOpDecoderKind.SCALAR_COLUMNS_TUPLE:
        return decode_scalar_columns_tuple(_expect_payload(spec, ScalarColumnsTupleSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.COALESCED_INSERT_RETURN_MAP:
        payload = spec.payload
        if isinstance(payload, CoalescedInsertReturnMapDecoderSpec):
            return decode_coalesced_insert_return_map(
                CoalescedInsertReturnMapSpec(payload.model_cls),
                raw,
                hydrator,
            )
        return decode_coalesced_insert_return_map(
            _expect_payload(spec, CoalescedInsertReturnMapSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.VECTOR_DIMENSION_VALIDATION:
        _expect_payload(spec, VectorDimensionValidationSpec)
        return decode_vector_dimension_validation(raw)
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_STORE_STATS:
        return decode_embedding_store_stats(_expect_payload(spec, EmbeddingStoreStatsSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_METADATA_VALIDATION:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_embedding_runtime_projection import (
            materialize_embedding_metadata_validation,
        )

        materialize_embedding_metadata_validation(raw)
        return None
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_MATERIALIZED_METADATA:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.embedding_metadata_runtime_projection import (
            materialize_embedding_materialized_metadata,
        )

        return materialize_embedding_materialized_metadata(raw)
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_HASH:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_embedding_runtime_projection import (
            materialize_embedding_hash,
        )

        return materialize_embedding_hash(raw)
    if spec.kind in {DomainPostOpDecoderKind.INTEGER_CURSOR_ROWS, DomainPostOpDecoderKind.BULK_INTEGER_CURSOR_CHANGES}:
        payload = spec.payload
        if isinstance(payload, BulkIntegerCursorChangesDecoderSpec):
            return decode_integer_cursor_rows(IntegerCursorRowsSpec(payload.last_cursor), raw)
        return decode_integer_cursor_rows(_expect_payload(spec, IntegerCursorRowsSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.CROSS_BRANCH_RESULT:
        return decode_cross_branch_result(_expect_payload(spec, CrossBranchResultSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.REQUIRED_ENCRYPTED_BLOB:
        payload = spec.payload
        if isinstance(payload, RequiredEncryptedBlobDecoderSpec):
            return decode_required_encrypted_blob(RequiredEncryptedBlobSpec(payload.blob_id), raw, hydrator)
        return decode_required_encrypted_blob(_expect_payload(spec, RequiredEncryptedBlobSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.WORKSPACE_NONCE:
        payload = spec.payload
        if isinstance(payload, WorkspaceNonceDecoderSpec):
            return decode_workspace_nonce(WorkspaceNonceSpec(payload.column_name, payload.require_row), raw)
        return decode_workspace_nonce(_expect_payload(spec, WorkspaceNonceSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.MERGE_RESULT:
        payload = _expect_payload(spec, MergeResultSpec)
        return decode_merge_result(raw, allow_empty_absent=payload.allow_empty_absent)
    if spec.kind is DomainPostOpDecoderKind.REPLAYED_REBASE_RESULT:
        return decode_replayed_rebase_result(_expect_payload(spec, ReplayedRebaseResultSpec), raw)
    # Closed decoder registry additions stay explicit; no generic runtime-ref
    # fallback is allowed for domain materialization.
    if spec.kind is DomainPostOpDecoderKind.SELECTED_UPDATE_RESULT:
        from impl.common.l2070_server_plan.steps.row_hydration import (
            materialize_selected_update_result_from_raw,
        )

        return materialize_selected_update_result_from_raw(
            _expect_payload(spec, SelectedUpdateResultDecoderSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.CACHE_GENERATION_MAP:
        payload = _expect_payload(spec, CacheGenerationMapDecoderSpec)
        from impl.common.l2070_server_plan.steps.cache_steps import (
            _fill_mode,
            _generation_map_from_raw,
        )

        return _generation_map_from_raw(
            raw,
            literal_tags=payload.literal_tags,
            fill_mode=_fill_mode(payload.fill_mode),
        )
    if spec.kind is DomainPostOpDecoderKind.EDGE_VIOLATION:
        payload = _expect_payload(spec, EdgeViolationDecoderSpec)
        if not raw:
            return None
        decode_edge_violations(payload, raw)
        return None
    if spec.kind is DomainPostOpDecoderKind.SESSION_VALIDATION:
        return decode_session_validation(_expect_payload(spec, SessionValidationDecoderSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.SESSION_LOOKUP_ROW:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.session_context_resolution import (
            _hydrate_session_lookup_row,
        )

        return _hydrate_session_lookup_row(raw)
    if spec.kind is DomainPostOpDecoderKind.PREPARED_CACHE_COMMIT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.cache_steps import (
            materialize_prepared_cache_commit,
        )

        return materialize_prepared_cache_commit(raw)
    if spec.kind is DomainPostOpDecoderKind.CLEANUP_RESULT:
        return decode_cleanup_result(_expect_payload(spec, CleanupResultDecoderSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.VERSIONED_TYPE_NAME_MAP:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_versioned_type_name_map(raw)
    if spec.kind is DomainPostOpDecoderKind.VERSIONED_NODE_METADATA_MAP:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_versioned_node_metadata_map(raw)
    if spec.kind is DomainPostOpDecoderKind.SQUASH_BRANCH_CONTEXT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_squash_branch_context(raw)
    if spec.kind is DomainPostOpDecoderKind.SQUASH_MERGE_CONTEXT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_squash_merge_context(raw)
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_VECTOR_CONFLICT_VALIDATION:
        payload = _expect_payload(spec, EmbeddingVectorConflictValidationDecoderSpec)
        materialize_embedding_vector_conflict_validation(payload, raw)
        return None
    if spec.kind in {
        DomainPostOpDecoderKind.RENEWABLE_ACCESS_VALIDATION,
        DomainPostOpDecoderKind.RENEWABLE_REFRESH_VALIDATION,
    }:
        if spec.kind is DomainPostOpDecoderKind.RENEWABLE_ACCESS_VALIDATION:
            return materialize_renewable_access_terminal_validation(
                _expect_payload(spec, RenewableAccessValidationDecoderSpec),
                raw,
                hydrator,
            )
        return materialize_renewable_refresh_terminal_validation(
            _expect_payload(spec, RenewableRefreshValidationDecoderSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_FAMILY_PROJECTION:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_renewable_credentials import (
            materialize_renewable_family_projection,
        )

        return materialize_renewable_family_projection(raw)
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_REFRESH_REPLAY_VALIDATION:
        materialize_renewable_refresh_replay_exception_validation(
            _expect_payload(spec, RenewableRefreshReplayValidationDecoderSpec),
            raw,
        )
        return None
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_REFRESH_ROTATE_VALIDATION:
        materialize_renewable_refresh_rotate_exception_validation(
            _expect_payload(spec, RenewableRefreshRotateValidationDecoderSpec),
            raw,
            hydrator,
        )
        return None
    _expect_empty_payload(spec)
    msg = f"Unsupported domain post-op decoder: {spec.kind.value}"
    raise ValueError(msg)


def decode_terminal_object_literal_payload(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Decode legacy literal-payload object contracts outside the generic interpreter."""

    literal_payload = spec.literal_payload if isinstance(spec.literal_payload, Mapping) else {}
    if spec.terminal_materializer is TerminalMaterializerKind.EMBEDDING_REQUIRE_NO_ROWS:
        if raw:
            message = str(literal_payload.get("message", "not found"))
            expected_count = literal_payload.get("expected_count")
            actual_count_column = literal_payload.get("actual_count_column")
            first_row = raw[0]
            if isinstance(expected_count, int) and isinstance(actual_count_column, str) and isinstance(first_row, Mapping):
                actual_count = first_row.get(actual_count_column)
                message = f"{message}; expected {expected_count} rows, resolved {actual_count}"
            raise ValueError(message)
        return None
    if (
        spec.behavior == PostOpBehavior.TERMINAL_OBJECT
        and isinstance(spec.literal_payload, Mapping)
        and spec.terminal_materializer is TerminalMaterializerKind.CACHE_GET_RESOLUTION
    ):
        from impl.common.l2070_server_plan.steps.cache_steps import (
            materialize_cache_get_resolution,
        )

        return materialize_cache_get_resolution(spec, raw)
    return DECODE_NOT_HANDLED


def decode_terminal_array_literal_payload(spec: ResultMaterializationSpec, raw: RawResult) -> object:
    """Decode legacy literal-payload array contracts outside the generic interpreter."""

    literal_payload = spec.literal_payload if isinstance(spec.literal_payload, Mapping) else {}
    if spec.terminal_materializer is TerminalMaterializerKind.GRAPH_BINDINGS:
        from impl.common.l2070_server_plan.steps.intent_graph import (
            GraphBindingMaterializationSpec,
            _process_graph_binding_rows,
        )

        binding_spec = literal_payload.get("binding_spec")
        if not isinstance(binding_spec, GraphBindingMaterializationSpec):
            msg = f"graph_bindings post-op requires a GraphBindingMaterializationSpec, got {type(binding_spec).__name__}"
            raise TypeError(msg)
        return _process_graph_binding_rows(list(raw), spec=binding_spec)
    if spec.terminal_materializer is TerminalMaterializerKind.SEARCH_WITH_META:
        from impl.common.l2070_server_plan.steps.search_payload import _project_search_rows_with_meta

        return _project_search_rows_with_meta(raw)
    if spec.terminal_materializer is TerminalMaterializerKind.DOLT_MATERIALIZED_REVISION_IDS:
        from impl.common.l7350_sparse_versioned_transactions.dolt_revision_ids import (
            commit_hash_to_revision_id,
        )

        return [
            commit_hash_to_revision_id(str(_row_dict(cast("Mapping[str, object]", row)).get("commit_hash")))
            for row in raw
            if _row_dict(cast("Mapping[str, object]", row)).get("commit_hash") is not None
        ]
    if spec.terminal_materializer is TerminalMaterializerKind.MATERIALIZATION_CANDIDATES:
        from impl.common.l7500_versioned_materialization.materialization_jobs import (
            MaterializationCandidate,
            MaterializationPriority,
        )
        from l1400_types import RevisionAnchorReason
        from l7000_versioned_schema.versioned_schema import RevisionId

        candidates: list[MaterializationCandidate] = []
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            revision_id = row_dict.get("revision_id")
            if revision_id is None:
                continue
            anchor_reason = row_dict.get("anchor_reason")
            raw_priority = row_dict.get("priority")
            priority_rank = 3 if raw_priority is None else int(cast("int | float | str | bytes", raw_priority))
            priority = {
                0: MaterializationPriority.HIGH,
                1: MaterializationPriority.MEDIUM,
                2: MaterializationPriority.LOW,
            }.get(priority_rank, MaterializationPriority.BACKGROUND)
            candidates.append(
                MaterializationCandidate(
                    revision_id=RevisionId(str(revision_id)),
                    anchor_reason=None if anchor_reason is None else RevisionAnchorReason(str(anchor_reason)),
                    priority=priority,
                ),
            )
        return candidates
    return DECODE_NOT_HANDLED


