class BranchRouteProofDecoderSpec:
    """Bind one typed branch-route proof relation to its compiled attempt."""

    scope_id: SpeculationScopeId
    attempt_id: SpeculationAttemptId
    intent_ids: tuple[SpeculationIntentId, ...]

    def __post_init__(self: BranchRouteProofDecoderSpec) -> None:
        if not self.scope_id:
            raise ValueError("A branch-route proof decoder requires a scope identity")
        if self.attempt_id < 0:
            raise ValueError("A branch-route proof decoder attempt cannot be negative")
        if not self.intent_ids or len(set(self.intent_ids)) != len(self.intent_ids):
            raise ValueError("A branch-route proof decoder requires unique intent identities")


