@dataclass(frozen=True, slots=True)
class DomainPostOpDecoderSpec[PayloadT: DomainPostOpDecoderPayload]:
    """One closed domain decoder and its statically typed payload."""

    kind: DomainPostOpDecoderKind
    payload: PayloadT

    def __post_init__(self: DomainPostOpDecoderSpec[PayloadT]) -> None:
        expected_payload_type = _DOMAIN_DECODER_PAYLOAD_TYPES.get(self.kind)
        if expected_payload_type is None:
            msg = f"Unsupported domain post-op decoder kind: {self.kind!r}"
            raise ValueError(msg)
        if not isinstance(self.payload, expected_payload_type):
            msg = f"{self.kind.value} requires payload {expected_payload_type.__name__}, got {type(self.payload).__name__}."
            raise TypeError(msg)
        _assert_no_runtime_behavior_escape(
            self.payload,
            path=f"DomainPostOpDecoderSpec[{self.kind.value}].payload",
            allow_pydantic_models=True,
        )


