_MERGE_RESULT_CANONICAL_COLUMNS = frozenset(
    {
        "status",
        "operation_id",
        "base_revision_id",
        "source_revision_id",
        "target_revision_id",
        "result_revision_id",
        "inserted",
        "updated",
        "deleted",
