@dataclass(frozen=True, slots=True)
class CompiledPostOp:
    """Closed post-processing operation attached to a compiled step."""

    kind: PostOpKind
    spec: ResultMaterializationSpec | ResultAssertionSpec
    runtime_symbol: PostOpRuntimeSymbol

    def __post_init__(self: CompiledPostOp) -> None:
        expected = post_op_runtime_symbol(self.spec)
        if self.runtime_symbol != expected:
            msg = f"Compiled post-op symbol {self.runtime_symbol!r} does not match exact operation {expected!r}."
            raise ValueError(msg)

    def __call__(
        self,
        raw: RawResult,
        hydrator: Hydrator[object],
    ) -> Any:
        """Materialize this closed post-op for tests and direct interpreters."""

        return materialize_compiled_post_op(self, raw, hydrator)

    @classmethod
    def materialize(cls, spec: ResultMaterializationSpec) -> CompiledPostOp:
        """Build a materialization operation."""

        return cls(
            PostOpKind.MATERIALIZE_RESULT,
            spec,
            PostOpRuntimeSymbol(post_op_runtime_symbol(spec)),
        )

    @classmethod
    def assert_result(cls, spec: ResultAssertionSpec) -> CompiledPostOp:
        """Build an assertion operation."""

        return cls(
            PostOpKind.ASSERT_RESULT,
            spec,
            PostOpRuntimeSymbol(post_op_runtime_symbol(spec)),
        )


