def graph_result_post_op(
    node_cls: type[DatabaseObjectRow[Any]],
    edge_cls: type[DatabaseObjectRow[Any]],
    *,
    node_columns: tuple[SqlColumnName, ...] | None = None,
    edge_columns: tuple[SqlColumnName, ...] | None = None,
) -> CompiledPostOp:
    """Materialize graph result rows from a SQL node-plus-edge relation."""
    if node_columns is None:
        node_columns = tuple(
            SqlColumnName(get_db_column_name(node_cls, DynamicFieldName(field_name))) for field_name in node_cls.model_fields
        )
    if edge_columns is None:
        edge_column_names = [get_db_column_name(edge_cls, DynamicFieldName(field_name)) for field_name in edge_cls.model_fields]
        for required_name in ("sys_id", "graph_sys_id", "source_sys_id", "target_sys_id"):
            required = SqlColumnName(required_name)
            if required not in edge_column_names:
                edge_column_names.append(required)
        edge_columns = tuple(SqlColumnName(column) for column in edge_column_names)

    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            domain_decoder=DomainPostOpDecoderSpec(
                DomainPostOpDecoderKind.GRAPH_RESULT,
                GraphResultDecoderSpec(
                    node_type=node_cls,
                    edge_type=edge_cls,
                    node_columns=node_columns,
                    edge_columns=edge_columns,
                ),
            ),
        ),
    )


