@dataclass(frozen=True, slots=True)
class _RuntimePayloadSchema:
    """Closed per-operation payload slots that are not ordinary scalar data."""

    exception_fields: frozenset[str] = frozenset()
    exception_type_fields: frozenset[str] = frozenset()
    model_type_fields: frozenset[str] = frozenset()
    pydantic_model_fields: frozenset[str] = frozenset()
    symbolic_scalar_fields: frozenset[str] = frozenset()
    compiled_post_op_fields: frozenset[str] = frozenset()

    def allows_exception_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return key in self.exception_fields and isinstance(value, Exception)

    def allows_exception_type_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return key in self.exception_type_fields and isinstance(value, type) and issubclass(value, Exception)

    def allows_model_type_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        if key not in self.model_type_fields:
            return False
        if isinstance(value, type):
            return True
        if isinstance(value, Sequence) and not isinstance(value, str | bytes | bytearray):
            return all(isinstance(item, type) for item in value)
        if isinstance(value, Mapping):
            return all(isinstance(item_key, str) and isinstance(item, type) for item_key, item in value.items())
        return False

    def allows_pydantic_model_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return key in self.pydantic_model_fields and isinstance(value, BaseModel)

    def allows_symbolic_scalar_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return key in self.symbolic_scalar_fields and isinstance(value, ScalarServerRef)

    def allows_compiled_post_op_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return key in self.compiled_post_op_fields and _runtime_builder_value_is_compiled_post_op(value)

    def allows_declared_field(self: _RuntimePayloadSchema, key: str, value: object) -> bool:
        return (
            self.allows_exception_field(key, value)
            or self.allows_exception_type_field(key, value)
            or self.allows_model_type_field(key, value)
            or self.allows_pydantic_model_field(key, value)
            or self.allows_symbolic_scalar_field(key, value)
            or self.allows_compiled_post_op_field(key, value)
        )


