@dataclass(frozen=True, slots=True)
class StructuredResultField:
    """Map one field, with optional canonical model or structured-array hydration.

    ``model_cls`` and ``structured_array`` are mutually exclusive. Optional nested
    fields accept ``None`` before result-model validation.
    """

    output_name: str
    source_column: str
    scalar_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE
    required: bool = True
    default_value: object | None = None
    model_cls: type[DatabaseObjectRow] | None = None
    structured_array: StructuredArraySpec | None = None

    def __post_init__(self: StructuredResultField) -> None:
        if not self.output_name:
            msg = "StructuredResultField.output_name must be non-empty."
            raise ValueError(msg)
        if not self.source_column:
            msg = f"Structured field {self.output_name!r} has no source column."
            raise ValueError(msg)
        if self.required and self.default_value is not None:
            msg = f"Required structured field {self.output_name!r} cannot declare a default."
            raise ValueError(msg)
        if self.model_cls is not None and self.structured_array is not None:
            raise ValueError("A structured field cannot declare both a model and an array.")
        if self.model_cls is not None:
            from l1000_schema.schema_def import DatabaseObjectRow

            if not issubclass(self.model_cls, DatabaseObjectRow):
                raise TypeError("A structured model field requires a database row class.")


@dataclass(frozen=True, slots=True)
class StructuredResultSpec:
    """Closed mapping from a SQL row contract to one Python result object."""

    result_cls: type[Any]
    fields: tuple[StructuredResultField, ...]
    derived_bool_fields: tuple[StructuredDerivedBoolField, ...] = ()
    require_one_row: bool = True
    allow_empty: bool = False
    merge_rows: bool = False
    empty_exception: type[Exception] | None = None
    empty_message: str | None = None
    return_empty_value: bool = False
    empty_value: object | None = None
    assertion_spec: ResultAssertionSpec | None = None

    def __post_init__(self: StructuredResultSpec) -> None:
        if not self.fields and not self.derived_bool_fields:
            msg = "StructuredResultSpec requires at least one field."
            raise ValueError(msg)
        seen: set[str] = set()
        for output_name in (
            *(field_spec.output_name for field_spec in self.fields),
            *(field_spec.output_name for field_spec in self.derived_bool_fields),
        ):
            if output_name in seen:
                msg = f"Duplicate structured result field {output_name!r}."
                raise ValueError(msg)
            seen.add(output_name)


