DECODE_NOT_HANDLED = object()


def _staged_commit_id_values(value: object) -> tuple[object, ...]:
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return tuple(value)
    text = str(value)
    if text.startswith("JSON(") and text.endswith(")"):
        text = text.removeprefix("JSON(").removesuffix(")")
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError):
        return ()
    if isinstance(parsed, Sequence) and not isinstance(parsed, (str, bytes)):
        return tuple(parsed)
    return ()


def _expect_payload[T](spec: DomainPostOpDecoderSpec, payload_type: type[T]) -> T:
    payload = spec.payload
    if not isinstance(payload, payload_type):
        msg = f"{spec.kind.value} expected payload {payload_type.__name__}, got {type(payload).__name__}."
        raise TypeError(msg)
    return payload


def _expect_empty_payload(spec: DomainPostOpDecoderSpec) -> None:
    if spec.payload is not None:
        msg = f"{spec.kind.value} does not accept a payload."
        raise TypeError(msg)


def _int_value(value: object) -> int:
    return int(cast("int | float | str | bytes", value))


def materialize_domain_decoder(
    spec: DomainPostOpDecoderSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Dispatch one closed domain decoder to its typed implementation."""

    require_post_op_interpreter_authority(operation="materialize_domain_decoder")
    if spec.kind is DomainPostOpDecoderKind.BRANCH_ROUTE_PROOF:
        proof_spec = _expect_payload(spec, BranchRouteProofDecoderSpec)
        from impl.common.l2070_server_plan.branch_route_speculation import (
            BranchRouteSpeculationMiss,
            decode_branch_route_proof_frame,
        )

        if not raw:
            raise ValueError("Persisted branch route proof rejected the selected branch or revision")
        frame = decode_branch_route_proof_frame(
            tuple(_require_row(raw, index) for index in range(len(raw))),
            expected_scope_id=proof_spec.scope_id,
            expected_attempt_id=proof_spec.attempt_id,
            expected_intent_ids=frozenset(proof_spec.intent_ids),
        )
        if not frame.admitted:
            raise BranchRouteSpeculationMiss(frame)
        return frame
    if spec.kind is DomainPostOpDecoderKind.GRAPH_PATH_EVIDENCE:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_graph import (
            _process_graph_path_evidence_rows,
        )

        return _process_graph_path_evidence_rows(list(raw))
    if spec.kind is DomainPostOpDecoderKind.GRAPH_RESULT:
        graph_payload = _expect_payload(spec, GraphResultDecoderSpec)
        from impl.common.l2070_server_plan.steps.intent_graph import _process_graph_result_rows
        from l9600_graphs.graph import GraphEdge, GraphNode

        if not (isinstance(graph_payload.node_type, type) and issubclass(graph_payload.node_type, GraphNode)):
            msg = f"graph_result decoder requires a GraphNode class, got {graph_payload.node_type!r}"
            raise TypeError(msg)
        if not (isinstance(graph_payload.edge_type, type) and issubclass(graph_payload.edge_type, GraphEdge)):
            msg = f"graph_result decoder requires a GraphEdge class, got {graph_payload.edge_type!r}"
            raise TypeError(msg)
        return _process_graph_result_rows(
            list(raw),
            graph_payload.node_type,
            graph_payload.edge_type,
            entity_kind_column=str(graph_payload.entity_kind_column),
            entity_id_column=str(graph_payload.entity_id_column),
            node_prefix=str(graph_payload.node_prefix),
            edge_prefix=str(graph_payload.edge_prefix),
            node_columns=tuple(str(column) for column in graph_payload.node_columns),
            edge_columns=tuple(str(column) for column in graph_payload.edge_columns),
        )
    if spec.kind is DomainPostOpDecoderKind.COMMIT_BRANCH_CONTEXT:
        _expect_payload(spec, CommitBranchContextSpec)
        return decode_commit_branch_context(raw)
    if spec.kind is DomainPostOpDecoderKind.COMMIT_BRANCH_FETCH:
        return decode_commit_branch_fetch(_expect_payload(spec, CommitBranchFetchSpec), raw)
    if spec.kind is DomainPostOpDecoderKind.CONTENT_STORE_ROW_LOOKUP:
        payload = spec.payload
        if isinstance(payload, ContentStoreRowLookupDecoderSpec):
            return decode_content_store_row_lookup(
                ContentStoreRowLookupSpec(payload.ref_id, payload.row_codec_kind),
                raw,
            )
        return decode_content_store_row_lookup(_expect_payload(spec, ContentStoreRowLookupSpec), raw)
    if spec.kind in {DomainPostOpDecoderKind.HISTORY_ENTRIES, DomainPostOpDecoderKind.HISTORY_ENTRIES_WITH_META}:
        payload = spec.payload
        if isinstance(payload, HistoryEntriesDecoderSpec):
            return decode_history_entries(
                HistoryEntriesSpec(payload.model_cls, payload.revision_model_cls),
                raw,
                hydrator,
            )
        return decode_history_entries(_expect_payload(spec, HistoryEntriesSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.HISTORY_CURSOR_PAGE:
        return decode_history_cursor_page(_expect_payload(spec, HistoryCursorPageSpec), raw, hydrator)
    if spec.kind is DomainPostOpDecoderKind.BRANCH_HISTORY_CURSOR_PAGE:
        return decode_branch_history_cursor_page(
