        return decode_versioned_node_metadata_map(raw)
    if spec.kind is DomainPostOpDecoderKind.SQUASH_BRANCH_CONTEXT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_squash_branch_context(raw)
    if spec.kind is DomainPostOpDecoderKind.SQUASH_MERGE_CONTEXT:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        return decode_squash_merge_context(raw)
    if spec.kind is DomainPostOpDecoderKind.EMBEDDING_VECTOR_CONFLICT_VALIDATION:
        payload = _expect_payload(spec, EmbeddingVectorConflictValidationDecoderSpec)
        materialize_embedding_vector_conflict_validation(payload, raw)
        return None
    if spec.kind in {
        DomainPostOpDecoderKind.RENEWABLE_ACCESS_VALIDATION,
        DomainPostOpDecoderKind.RENEWABLE_REFRESH_VALIDATION,
    }:
        if spec.kind is DomainPostOpDecoderKind.RENEWABLE_ACCESS_VALIDATION:
            return materialize_renewable_access_terminal_validation(
                _expect_payload(spec, RenewableAccessValidationDecoderSpec),
                raw,
                hydrator,
            )
        return materialize_renewable_refresh_terminal_validation(
            _expect_payload(spec, RenewableRefreshValidationDecoderSpec),
            raw,
            hydrator,
        )
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_FAMILY_PROJECTION:
        _expect_payload(spec, EmptyDomainDecoderPayload)
        from impl.common.l2070_server_plan.steps.intent_renewable_credentials import (
            materialize_renewable_family_projection,
        )

        return materialize_renewable_family_projection(raw)
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_REFRESH_REPLAY_VALIDATION:
        materialize_renewable_refresh_replay_exception_validation(
            _expect_payload(spec, RenewableRefreshReplayValidationDecoderSpec),
            raw,
        )
        return None
    if spec.kind is DomainPostOpDecoderKind.RENEWABLE_REFRESH_ROTATE_VALIDATION:
        materialize_renewable_refresh_rotate_exception_validation(
            _expect_payload(spec, RenewableRefreshRotateValidationDecoderSpec),
            raw,
            hydrator,
        )
        return None
    _expect_empty_payload(spec)
    msg = f"Unsupported domain post-op decoder: {spec.kind.value}"
    raise ValueError(msg)


def decode_terminal_object_literal_payload(
    spec: ResultMaterializationSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Decode legacy literal-payload object contracts outside the generic interpreter."""

    literal_payload = spec.literal_payload if isinstance(spec.literal_payload, Mapping) else {}
    if spec.terminal_materializer is TerminalMaterializerKind.EMBEDDING_REQUIRE_NO_ROWS:
        if raw:
            message = str(literal_payload.get("message", "not found"))
            expected_count = literal_payload.get("expected_count")
            actual_count_column = literal_payload.get("actual_count_column")
            first_row = raw[0]
            if isinstance(expected_count, int) and isinstance(actual_count_column, str) and isinstance(first_row, Mapping):
                actual_count = first_row.get(actual_count_column)
                message = f"{message}; expected {expected_count} rows, resolved {actual_count}"
            raise ValueError(message)
        return None
    if (
        spec.behavior == PostOpBehavior.TERMINAL_OBJECT
        and isinstance(spec.literal_payload, Mapping)
        and spec.terminal_materializer is TerminalMaterializerKind.CACHE_GET_RESOLUTION
    ):
        from impl.common.l2070_server_plan.steps.cache_steps import (
            materialize_cache_get_resolution,
        )

        return materialize_cache_get_resolution(spec, raw)
    return DECODE_NOT_HANDLED


def decode_terminal_array_literal_payload(spec: ResultMaterializationSpec, raw: RawResult) -> object:
    """Decode legacy literal-payload array contracts outside the generic interpreter."""

    literal_payload = spec.literal_payload if isinstance(spec.literal_payload, Mapping) else {}
    if spec.terminal_materializer is TerminalMaterializerKind.GRAPH_BINDINGS:
        from impl.common.l2070_server_plan.steps.intent_graph import (
            GraphBindingMaterializationSpec,
            _process_graph_binding_rows,
        )

        binding_spec = literal_payload.get("binding_spec")
        if not isinstance(binding_spec, GraphBindingMaterializationSpec):
            msg = f"graph_bindings post-op requires a GraphBindingMaterializationSpec, got {type(binding_spec).__name__}"
            raise TypeError(msg)
        return _process_graph_binding_rows(list(raw), spec=binding_spec)
    if spec.terminal_materializer is TerminalMaterializerKind.SEARCH_WITH_META:
        from impl.common.l2070_server_plan.steps.search_payload import _project_search_rows_with_meta

        return _project_search_rows_with_meta(raw)
    if spec.terminal_materializer is TerminalMaterializerKind.DOLT_MATERIALIZED_REVISION_IDS:
        from impl.common.l7350_sparse_versioned_transactions.dolt_revision_ids import (
            commit_hash_to_revision_id,
        )

        return [
            commit_hash_to_revision_id(str(_row_dict(cast("Mapping[str, object]", row)).get("commit_hash")))
            for row in raw
            if _row_dict(cast("Mapping[str, object]", row)).get("commit_hash") is not None
        ]
    if spec.terminal_materializer is TerminalMaterializerKind.MATERIALIZATION_CANDIDATES:
        from impl.common.l7500_versioned_materialization.materialization_jobs import (
            MaterializationCandidate,
            MaterializationPriority,
        )
        from l1400_types import RevisionAnchorReason
        from l7000_versioned_schema.versioned_schema import RevisionId

        candidates: list[MaterializationCandidate] = []
        for row in raw:
            row_dict = _row_dict(cast("Mapping[str, object]", row))
            revision_id = row_dict.get("revision_id")
            if revision_id is None:
                continue
            anchor_reason = row_dict.get("anchor_reason")
            raw_priority = row_dict.get("priority")
            priority_rank = 3 if raw_priority is None else int(cast("int | float | str | bytes", raw_priority))
            priority = {
                0: MaterializationPriority.HIGH,
                1: MaterializationPriority.MEDIUM,
                2: MaterializationPriority.LOW,
            }.get(priority_rank, MaterializationPriority.BACKGROUND)
            candidates.append(
                MaterializationCandidate(
                    revision_id=RevisionId(str(revision_id)),
                    anchor_reason=None if anchor_reason is None else RevisionAnchorReason(str(anchor_reason)),
                    priority=priority,
                ),
            )
        return candidates
    return DECODE_NOT_HANDLED


