def decode_versioned_type_name_map(raw: RawResult) -> dict[str, str]:
    """Build ``object id -> type name`` maps from SQL versioned type rows."""

    result: dict[str, str] = {}
    for row in raw:
        row_dict = dict(row)
        sys_id = row_dict.get("sys_id")
        type_name = row_dict.get("type_name")
        if sys_id is None or type_name is None:
