            raise ValueError(msg)
        return None
    row = _row_dict(cast("Mapping[str, object]", raw[0]))
    value = row.get(spec.column_name)
    if not isinstance(value, bytes):
        msg = f"Workspace secret materialization requires canonical bytes, got {type(value).__name__}."
