def decode_merge_result(raw: RawResult, *, allow_empty_absent: bool = False) -> object:
    """Decode merge result rows."""

    if not raw:
        if allow_empty_absent:
            return None
        msg = "Merge result SQL rows were empty."
        raise RuntimeError(msg)
    row = _row_dict(cast("Mapping[str, object]", raw[0]))
    actual_columns = frozenset(row)
    if actual_columns != _MERGE_RESULT_CANONICAL_COLUMNS:
        missing = tuple(sorted(_MERGE_RESULT_CANONICAL_COLUMNS - actual_columns))
        unexpected = tuple(sorted(actual_columns - _MERGE_RESULT_CANONICAL_COLUMNS))
        msg = f"Merge result requires canonical columns; missing={missing!r}, unexpected={unexpected!r}."
        raise ValueError(msg)

    from impl.common.l7450_versioned_merge.merge_types import (
        MergeApplyStats,
        MergeConflict,
        MergeResult,
        MergeStatus,
    )
    from l1400_types import SysId
    from l7000_versioned_schema.versioned_schema import RevisionId

    status_raw = row["status"]
    if status_raw is None:
        msg = "Merge result status cannot be null."
        raise ValueError(msg)
    status = status_raw if isinstance(status_raw, MergeStatus) else MergeStatus(str(status_raw))
    conflicts_raw = coerce_scalar_value(row["conflicts"], ScalarCoercionKind.JSON)
    if not isinstance(conflicts_raw, Sequence) or isinstance(conflicts_raw, str | bytes):
        msg = "Merge result conflicts must be one declared JSON array."
        raise TypeError(msg)

    conflicts: list[MergeConflict] = []
    for conflict in cast("Sequence[Mapping[str, object]]", conflicts_raw):
        source_deleted = _coerce_json_bool(conflict.get("source_sys_deleted"))
        target_deleted = _coerce_json_bool(conflict.get("target_sys_deleted"))
        conflicts.append(
            MergeConflict(
                table_name=str(conflict.get("table_name", "")),
                object_id=SysId(str(conflict["object_id"])),
                left_change="delete" if source_deleted else "modify",
                right_change="delete" if target_deleted else "modify",
                base=None,
                left=None,
                right=None,
            ),
        )

    operation_raw = row["operation_id"]
    base_raw = row["base_revision_id"]
    source_raw = row["source_revision_id"]
    target_raw = row["target_revision_id"]
    result_raw = row["result_revision_id"]
    if source_raw is None:
        msg = (
            "Merge result SQL row did not include source_revision_id; "
            f"published_columns={tuple(sorted(str(column) for column in row))!r}."
        )
        raise RuntimeError(msg)

    return MergeResult(
        status=status,
        operation_id=SysId(str(operation_raw)) if operation_raw is not None else None,
        base_revision_id=RevisionId(str(base_raw)) if base_raw is not None else None,
        source_revision_id=RevisionId(str(source_raw)),
        target_revision_id=RevisionId(str(target_raw)) if target_raw is not None else None,
        result_revision_id=RevisionId(str(result_raw)) if result_raw is not None else None,
        applied_changes=MergeApplyStats(
            inserted=_int_value(coerce_scalar_value(row["inserted"], ScalarCoercionKind.INT)),
            updated=_int_value(coerce_scalar_value(row["updated"], ScalarCoercionKind.INT)),
            deleted=_int_value(coerce_scalar_value(row["deleted"], ScalarCoercionKind.INT)),
        ),
        conflicts=conflicts,
    )


def decode_replayed_rebase_result(spec: ReplayedRebaseResultSpec, raw: RawResult) -> object:
    """Decode replayed rebase result rows."""

    if not raw:
        msg = "Replayed rebase SQL result did not include replay facts."
