    *,
    known_results: Mapping[SqlTableName, bool],
    unknown_names: Sequence[SqlTableName],
    result_columns: Sequence[str],
) -> CompiledPostOp:
    """Merge known table-existence values with SQL-projected unknown probes."""

    if len(unknown_names) != len(result_columns):
        msg = "table_exists_many_post_op requires one result column per unknown table name."
        raise ValueError(msg)
    return CompiledPostOp.materialize(
        ResultMaterializationSpec(
            behavior=PostOpBehavior.TERMINAL_OBJECT,
            domain_decoder=table_exists_many_decoder(
