    def __post_init__(self: CompoundResultSpec) -> None:
        if not self.label_columns:
            msg = "CompoundResultSpec requires at least one label column."
            raise ValueError(msg)
        if not self.children:
            msg = "CompoundResultSpec requires at least one child."
            raise ValueError(msg)
        child_labels = tuple(child.label for child in self.children)
        if len(set(child_labels)) != len(child_labels):
            msg = f"Duplicate compound result labels: {child_labels!r}"
            raise ValueError(msg)
        if self.result_label not in set(child_labels):
            msg = f"Compound result label {self.result_label!r} is not declared."
            raise ValueError(msg)


