        return _DOMAIN_DECODER_BEHAVIOR[kind]
    except KeyError as exc:
        msg = f"Unsupported domain post-op decoder kind: {kind!r}"
        raise ValueError(msg) from exc


class TerminalObjectEmptyKind(StrEnum):
    """Closed exception behavior for an empty terminal object relation."""

    OBJECT_NOT_FOUND = "object_not_found"
    PROGRAMMING_ERROR = "programming_error"
    VALUE_ERROR = "value_error"


@dataclass(frozen=True, slots=True)
class TerminalObjectEmptySpec:
    """Compile-time-selected empty relation behavior for object hydration."""

    kind: TerminalObjectEmptyKind
    message: str | None = None
    object_id: object | None = None


class ScalarAggregationKind(StrEnum):
    """Declared aggregation applied while materializing one scalar column."""

    NONE = "none"
    SUM_ROWS = "sum_rows"


@dataclass(frozen=True, slots=True)
class ResultMaterializationSpec:
    """Declarative final-result materialization spec."""

    behavior: PostOpBehavior | None = None
    model_cls: type[DatabaseObjectRow[Any]] | None = None
    input_relation: DeclaredResultRelation | None = None
    target_type: type[Any] | None = None
    column: str | None = None
    columns: tuple[str, ...] = ()
    row_index: int = 0
    literal_payload: object | None = None
    terminal_literal: LiteralResult | DecoderConfig | None = None
    result_cls: type[Any] | None = None
    default_value: object | None = None
    use_default_on_empty: bool = False
    first_row_scalar: bool = False
    scalar_coercion: ScalarCoercionKind = ScalarCoercionKind.NONE
    scalar_aggregation: ScalarAggregationKind = ScalarAggregationKind.NONE
    scalar_value_column: LockedColumnName | None = None
    strict_one: bool = False
    raw_mode: bool = False
    empty_rows_exception: type[Exception] | None = None
    select_columns: tuple[str, ...] | None = None
    error_message: str | None = None
    # Empty-object semantics are selected during compilation; literal payloads
    # carry data only and must never act as runtime dispatch dictionaries.
    terminal_object_empty: TerminalObjectEmptySpec | None = None
    terminal_materializer: TerminalMaterializerKind | None = None
    scalar_tuple: ScalarTupleResultSpec | None = None
    scalar_row_value: ScalarRowValueSpec[Any] | None = None
    assertion_from_row: ResultAssertionFromRowSpec[Any] | None = None
    structured_result: StructuredResultSpec | None = None
    structured_array: StructuredArraySpec | None = None
    revision_cache_tags: RevisionCacheTagsSpec | None = None
    conditional_fired_labels: ConditionalFiredLabelsSpec | None = None
    compound_result: CompoundResultSpec | None = None
    domain_decoder: DomainPostOpDecoderSpec | None = None
    tuple_query_projection_config: object | None = None
    inline_large_column_query_config: object | None = None
    blob_diff_block_size: int | None = None
    two_way_diff_config: object | None = None
    three_way_diff_config: object | None = None
    vector_search_results_config: object | None = None
    vector_search_id_scores_config: object | None = None
    unversioned_vector_scores_config: object | None = None
    embedding_worker_dispatch_groups: bool = False

    def __post_init__(self: ResultMaterializationSpec) -> None:
        if self.behavior is None:
            msg = "ResultMaterializationSpec requires explicit PostOpBehavior metadata."
            raise ValueError(msg)
        if self.target_type is None and self.model_cls is not None:
            object.__setattr__(self, "target_type", self.model_cls)
        if self.scalar_aggregation is not ScalarAggregationKind.NONE:
            if self.scalar_value_column is None:
                msg = "Scalar aggregation requires a declared LockedColumnName value column."
                raise ValueError(msg)
            if self.column != self.scalar_value_column.to_row_key():
                msg = (
                    "Scalar aggregation column does not match its declared locked value column: "
                    f"column={self.column!r}, scalar_value_column={self.scalar_value_column!r}."
                )
                raise ValueError(msg)
        if self.terminal_literal is not None:
            if self.literal_payload is not None:
                msg = "ResultMaterializationSpec accepts literal_payload or terminal_literal, not both."
                raise ValueError(msg)
            literal_payload = (
                self.terminal_literal.value if isinstance(self.terminal_literal, LiteralResult) else self.terminal_literal.payload
            )
            object.__setattr__(self, "literal_payload", literal_payload)
        if not self.columns and self.select_columns is not None:
            object.__setattr__(self, "columns", tuple(self.select_columns))
        if self.structured_result is not None and self.behavior is not PostOpBehavior.TERMINAL_OBJECT:
            msg = "structured_result requires TERMINAL_OBJECT behavior."
            raise ValueError(msg)
        if self.structured_array is not None and self.behavior is not PostOpBehavior.TERMINAL_ARRAY:
            msg = "structured_array requires TERMINAL_ARRAY behavior."
            raise ValueError(msg)
        if self.revision_cache_tags is not None and self.behavior is not PostOpBehavior.TERMINAL_ARRAY:
            msg = "revision_cache_tags requires TERMINAL_ARRAY behavior."
            raise ValueError(msg)
        if self.terminal_materializer is not None:
            array_materializers = {
                TerminalMaterializerKind.DOLT_MATERIALIZED_REVISION_IDS,
                TerminalMaterializerKind.GRAPH_BINDINGS,
                TerminalMaterializerKind.MATERIALIZATION_CANDIDATES,
                TerminalMaterializerKind.SEARCH_WITH_META,
            }
            expected_behavior = (
                PostOpBehavior.TERMINAL_ARRAY if self.terminal_materializer in array_materializers else PostOpBehavior.TERMINAL_OBJECT
            )
            if self.behavior is not expected_behavior:
                msg = f"{self.terminal_materializer.value} requires {expected_behavior.value} behavior."
                raise ValueError(msg)
            raw_materializers = {
                TerminalMaterializerKind.EXACT_SINGLE_ROW,
                TerminalMaterializerKind.PERMITTED_RAW_ROW,
                TerminalMaterializerKind.REQUIRED_RAW_ROW,
            }
            requires_raw_mode = self.terminal_materializer in raw_materializers
            if self.raw_mode is not requires_raw_mode:
                mode = "raw" if requires_raw_mode else "normalized"
                msg = f"{self.terminal_materializer.value} requires {mode} row mode."
                raise ValueError(msg)
        if self.conditional_fired_labels is not None and self.behavior is not PostOpBehavior.TERMINAL_OBJECT:
            msg = "conditional_fired_labels requires TERMINAL_OBJECT behavior."
            raise ValueError(msg)
        if self.compound_result is not None and self.behavior is not PostOpBehavior.TERMINAL_ARRAY:
            msg = "compound_result requires TERMINAL_ARRAY behavior."
            raise ValueError(msg)
        if self.scalar_tuple is not None and self.behavior is not PostOpBehavior.TERMINAL_SCALAR:
            msg = "scalar_tuple requires TERMINAL_SCALAR behavior."
            raise ValueError(msg)
        if self.scalar_row_value is not None and self.behavior is not PostOpBehavior.TERMINAL_SCALAR:
            msg = "scalar_row_value requires TERMINAL_SCALAR behavior."
            raise ValueError(msg)
        if self.assertion_from_row is not None and self.behavior is not PostOpBehavior.EXCEPTION_ONLY:
            msg = "assertion_from_row requires EXCEPTION_ONLY behavior."
            raise ValueError(msg)
        closed_terminal_specs = tuple(
            spec
            for spec in (
                self.scalar_tuple,
                self.scalar_row_value,
                self.assertion_from_row,
                self.structured_result,
                self.structured_array,
                self.revision_cache_tags,
                self.conditional_fired_labels,
                self.terminal_materializer,
                self.compound_result,
                self.domain_decoder,
            )
            if spec is not None
        )
        if len(closed_terminal_specs) > 1:
            msg = "ResultMaterializationSpec accepts exactly one closed terminal spec."
            raise ValueError(msg)
        if self.domain_decoder is not None:
            expected_behavior = domain_decoder_behavior(self.domain_decoder.kind)
            if self.behavior is not expected_behavior:
                msg = f"{self.domain_decoder.kind.value} requires {expected_behavior.value} behavior."
                raise ValueError(msg)
        if isinstance(self.literal_payload, Mapping) and "literal_post_op" in self.literal_payload:
            msg = "literal_post_op marker dictionaries are forbidden; use LiteralResult."
            raise TypeError(msg)
        _assert_no_runtime_behavior_escape(
            self.literal_payload,
            path="ResultMaterializationSpec.literal_payload",
            allow_pydantic_models=True,
        )
        _assert_no_runtime_behavior_escape(
            self.default_value,
            path="ResultMaterializationSpec.default_value",
            allow_pydantic_models=True,
        )
        for opaque_slot_name in (
            "tuple_query_projection_config",
            "inline_large_column_query_config",
            "two_way_diff_config",
            "three_way_diff_config",
            "vector_search_results_config",
            "vector_search_id_scores_config",
            "unversioned_vector_scores_config",
        ):
            _assert_no_runtime_behavior_escape(
                getattr(self, opaque_slot_name),
                path=f"ResultMaterializationSpec.{opaque_slot_name}",
                allow_pydantic_models=True,
            )
        if self.domain_decoder is not None and self.domain_decoder.payload is not None:
            _assert_no_runtime_behavior_escape(
                self.domain_decoder.payload,
                path=f"ResultMaterializationSpec.domain_decoder[{self.domain_decoder.kind.value}].payload",
                allow_pydantic_models=True,
            )


