def _staged_commit_id_values(value: object) -> tuple[object, ...]:
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return tuple(value)
    text = str(value)
    if text.startswith("JSON(") and text.endswith(")"):
        text = text.removeprefix("JSON(").removesuffix(")")
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError):
        return ()
    if isinstance(parsed, Sequence) and not isinstance(parsed, (str, bytes)):
        return tuple(parsed)
    return ()


def _expect_payload[T](spec: DomainPostOpDecoderSpec, payload_type: type[T]) -> T:
    payload = spec.payload
    if not isinstance(payload, payload_type):
        msg = f"{spec.kind.value} expected payload {payload_type.__name__}, got {type(payload).__name__}."
        raise TypeError(msg)
    return payload


def _expect_empty_payload(spec: DomainPostOpDecoderSpec) -> None:
    if spec.payload is not None:
        msg = f"{spec.kind.value} does not accept a payload."
        raise TypeError(msg)


def _int_value(value: object) -> int:
