def decode_scalar_columns_tuple(spec: ScalarColumnsTupleSpec, raw: RawResult) -> object:
    """Decode explicitly declared scalar columns as a tuple."""

    if not raw:
        if spec.return_none_on_empty:
            return None
        return tuple(spec.default_values)
    row = _row_dict(cast("Mapping[str, object]", raw[0]))
    values: list[object] = []
    for column_name, default in zip(spec.column_names, spec.default_values, strict=True):
        value = row.get(column_name)
        if value is None:
            value = default
        if isinstance(default, bool):
            values.append(coerce_scalar_value(value, ScalarCoercionKind.BOOL))
            continue
        if isinstance(default, int) and not isinstance(value, bool):
            values.append(int(cast("int | float | str | bytes", value)))
            continue
        values.append(value)
    return tuple(values)


def _declared_edge_cycle_path(row: Mapping[str, object]) -> list[str]:
    path_value = row.get("path_text")
    if not isinstance(path_value, str):
        msg = "Cycle violation facts require a declared path_text value."
        raise TypeError(msg)
    path = path_value.split(",")
    if len(path) < 2 or path[0] != path[-1] or any(not node_id for node_id in path):
        msg = "Cycle violation path_text must contain one closed ordered path."
        raise ValueError(msg)
    return path


def decode_edge_violation(spec: EdgeViolationDecoderSpec, row: Mapping[str, object]) -> None:
    """Raise the graph exception represented by a closed SQL violation fact."""

    edge_base = str(row.get("edge_base") or spec.edge_base or "")
    violation_kind = str(spec.violation_kind or row.get("result_kind") or "")
    if not edge_base:
        msg = "edge violation materialization requires edge_base."
        raise ValueError(msg)
    source = str(row.get("source_sys_id", ""))
    target = str(row.get("target_sys_id", ""))
    result_kind = row.get("result_kind")
    if violation_kind in {"single_parent", "parent_conflict"} or result_kind == "parent_conflict":
        from l1100_exceptions.graph_exceptions import MultipleParentsError

        parent_ids_raw = row.get("parent_ids")
        parent_ids = [] if parent_ids_raw is None else [part for part in str(parent_ids_raw).split(",") if part]
        parent_count = row.get("parent_count")
        raise MultipleParentsError(
            edge_base,
            target,
            _int_value(parent_count or len(parent_ids)),
            parent_ids,
        )
    if violation_kind in {"cycle", "cycle_detected"} or result_kind == "cycle_detected":
        from l1100_exceptions.graph_exceptions import TreeCycleError

        raise TreeCycleError(edge_base, _declared_edge_cycle_path(row))
    if violation_kind == "tree_validity":
        if result_kind == "parent_conflict":
            from l1100_exceptions.graph_exceptions import MultipleParentsError

            parent_ids_raw = row.get("parent_ids")
            parent_ids = [] if parent_ids_raw is None else [part for part in str(parent_ids_raw).split(",") if part]
            parent_count = row.get("parent_count")
            raise MultipleParentsError(
                edge_base,
                target,
                _int_value(parent_count or len(parent_ids)),
                parent_ids,
            )
        from l1100_exceptions.graph_exceptions import TreeCycleError

        raise TreeCycleError(edge_base, _declared_edge_cycle_path(row))
    if violation_kind == "symmetric":
        from l1100_exceptions.graph_exceptions import AsymmetricEdgeError

        raise AsymmetricEdgeError(edge_base, [(source, target)])
    if result_kind == "polymorphic_discriminator":
        from l1100_exceptions.exceptions import IntegrityError

        raise IntegrityError(f"Cannot change polymorphic discriminator for '{edge_base}'")
    if violation_kind == "graph_identity":
        from l1100_exceptions.exceptions import IntegrityError

        raise IntegrityError(
            f"graph_sys_id is stable across versions for '{edge_base}'; delete and recreate the graph member",
        )
    if violation_kind == "duplicate" or "edge_count" in row:
        from l1100_exceptions.exceptions import IntegrityError

        raise IntegrityError(f"Duplicate edge in '{edge_base}'")
    from l1100_exceptions.exceptions import IntegrityError

    raise IntegrityError(f"Dangling edge in '{edge_base}'")


def decode_edge_violations(spec: EdgeViolationDecoderSpec, raw: RawResult) -> None:
    """Raise one graph exception from the complete SQL violation relation."""
    rows = [_row_dict(cast("Mapping[str, object]", row)) for row in raw]
    if spec.violation_kind == "symmetric":
        from l1100_exceptions.graph_exceptions import AsymmetricEdgeError

        first = rows[0]
        edge_base = str(first.get("edge_base") or spec.edge_base or "")
        if not edge_base:
            msg = "edge violation materialization requires edge_base."
            raise ValueError(msg)
        missing_reciprocals = [
            (
                str(row.get("source_sys_id", "")),
                str(row.get("target_sys_id", "")),
            )
            for row in rows
        ]
        raise AsymmetricEdgeError(edge_base, missing_reciprocals)
    decode_edge_violation(spec, rows[0])


def decode_session_validation(
    spec: SessionValidationDecoderSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Validate a SQL-selected session row and return its closed state."""

    from datetime import datetime

    from impl.common.l2070_server_plan.steps.session_validation import (
        SessionAuthValidationRow,
        ValidatedSessionState,
        _check_session_state,
        _coerce_validated_user_id,
        convert_session_row_db_to_python,
    )
    from l1100_exceptions.security import SessionValidationError
    from l1300_session.session import SessionId

    if not raw:
        unresolved_session_id = SessionId.unresolved()
        raise SessionValidationError(
            f"Session {unresolved_session_id} does not exist",
            session_id=unresolved_session_id,
            reason="not_found",
        )
    del hydrator
    raw_row = _row_dict(_require_row(raw))
    converted = convert_session_row_db_to_python(raw_row)
    raw_session_id = converted.get("sys_id")
    if raw_session_id is None:
        unresolved_session_id = SessionId.unresolved()
        raise SessionValidationError(
            f"Session {unresolved_session_id} does not exist",
            session_id=unresolved_session_id,
            reason="not_found",
        )
    session_id = SessionId(str(raw_session_id))
    if converted.get("session_type") is None:
        _check_session_state(None, session_id)
        return ValidatedSessionState(
            session_id=session_id,
            user_id=None,
            session_type="system",
            expires_at=None,
            cacheable=False,
        )
    session = SessionAuthValidationRow.model_validate(
        {
            "sys_id": converted.get("sys_id"),
            "session_type": converted.get("session_type"),
            "sys_closed_at": converted.get("closed_at"),
            "expires_at": converted.get("expires_at"),
            "user_id": converted.get("user_id"),
            "source": converted.get("source"),
            "revoked_at": converted.get("revoked_at"),
            "parent_session_id": converted.get("parent_session_id"),
            "parent_closed_at": raw_row.get("parent_closed_at"),
            "parent_expires_at": raw_row.get("parent_expires_at"),
            "parent_user_id": raw_row.get("parent_user_id"),
            "parent_source": raw_row.get("parent_source"),
        },
    )
    _check_session_state(session, session_id)
    session_type = getattr(session, "session_type", None)
    expires_at = getattr(session, "expires_at", None)
    return ValidatedSessionState(
        session_id=session_id,
        user_id=_coerce_validated_user_id(getattr(session, "user_id", None)),
        session_type=session_type if session_type in {"service", "system"} else "user",
        expires_at=expires_at if isinstance(expires_at, datetime) else None,
        cacheable=getattr(session, "source", None) != "ripple",
    )


