def _coalesced_insert_return_ordinal(row: Mapping[str, object]) -> int:
    ordinal = row.get("__ordinal", 0)
    if ordinal is None:
        return 0
    if isinstance(ordinal, bool):
        return int(ordinal)
    if isinstance(ordinal, int):
        return ordinal
    if isinstance(ordinal, str):
        return int(ordinal)
    msg = f"Coalesced insert return row has invalid __ordinal value: {ordinal!r}"
    raise TypeError(msg)


def decode_coalesced_insert_return_map(
    spec: CoalescedInsertReturnMapSpec,
    raw: RawResult,
    hydrator: Hydrator[Any],
) -> object:
    """Decode coalesced insert rows into their source ref result map."""

    from impl.common.l2070_server_plan.steps.row_hydration import _hydrate_row

    grouped: dict[str, tuple[bool, list[Mapping[str, object]]]] = {}
    for row in raw:
        row_mapping = cast("Mapping[str, object]", row)
        ref_id = row_mapping.get("__ref_id")
        if not isinstance(ref_id, str) or not ref_id:
            msg = "Coalesced insert return rows must include a non-empty __ref_id."
            raise ValueError(msg)
        return_many = bool(row_mapping.get("__return_many", False))
        _existing_return_many, rows = grouped.setdefault(ref_id, (return_many, []))
        rows.append(row_mapping)

    result: dict[str, object] = {}
    for ref_id, (return_many, rows) in grouped.items():
        ordered_rows = sorted(rows, key=_coalesced_insert_return_ordinal)
        hydrated = [_hydrate_row(spec.model_cls, _row_dict(row), hydrator) for row in ordered_rows]
        if return_many:
            result[ref_id] = hydrated
            continue
        if len(hydrated) != 1:
            msg = f"Expected exactly one coalesced insert return row for {ref_id!r}, got {len(hydrated)}."
            raise ValueError(msg)
        result[ref_id] = hydrated[0]
    return result


