def decode_commit_branch_context(raw: RawResult) -> object:
    """Decode commit-branch context rows."""

    from impl.common.l2070_server_plan.steps.intent_transaction import CommitBranchCtx
    from l1200_versioned_ids import BranchId, StagedCommitId
    from l7000_versioned_schema.versioned_schema import RevisionId

    branch_id: BranchId | None = None
    current_tip_revision_id: RevisionId | None = None
    new_revision_id: RevisionId | None = None
    staged_commit_ids: list[StagedCommitId] = []
    seen_staged: set[str] = set()
    for row in raw:
        row_dict = _row_dict(cast("Mapping[str, object]", row))
        if branch_id is None and row_dict.get("branch_id") is not None:
            branch_id = BranchId(str(row_dict["branch_id"]))
        if current_tip_revision_id is None and row_dict.get("current_tip_revision_id") is not None:
            current_tip_revision_id = RevisionId(str(row_dict["current_tip_revision_id"]))
        if new_revision_id is None and row_dict.get("new_revision_id") is not None:
            new_revision_id = RevisionId(str(row_dict["new_revision_id"]))
        staged_raw = row_dict.get("staged_commit_id")
        if staged_raw is not None:
            staged_key = str(staged_raw)
            if staged_key not in seen_staged:
                staged_commit_ids.append(StagedCommitId(staged_key))
                seen_staged.add(staged_key)
        staged_many = row_dict.get("staged_commit_ids")
        for staged_value in _staged_commit_id_values(staged_many):
            staged_key = str(staged_value)
            if staged_key not in seen_staged:
                staged_commit_ids.append(StagedCommitId(staged_key))
                seen_staged.add(staged_key)
    if branch_id is None or new_revision_id is None:
        observed_columns = tuple(
            tuple(str(column) for column in cast("Mapping[str, object]", row).keys()) for row in raw if isinstance(row, Mapping)
        )
        msg = f"Commit-branch context SQL rows did not include branch_id and new_revision_id; observed_columns={observed_columns!r}"
        raise RuntimeError(msg)
    return CommitBranchCtx(
        branch_id=branch_id,
        current_tip_revision_id=current_tip_revision_id,
        staged_commit_ids=tuple(staged_commit_ids),
        new_revision_id=new_revision_id,
    )


